ST.xhtml:
{region "§0 Session simulation & aiguillage"}
// === 🧪 §0 SIMULATION & SÉLECTION DE SOURCE ===
// 🎯 Producteur unique des aiguillages Reel/Simu par domaine (HwReal vs HwSim -> HwIn).

SimulationModeRise(CLK := GVL_Simulation.SimulationModeActive);
SimulationModeFall(CLK := GVL_Simulation.SimulationModeActive);

// 🧪 Activation par domaine = SUR FRONT UNIQUEMENT : Sim*Active bascule au front montant
// (TRUE) et au front descendant (FALSE) de SimulationModeActive, jamais en niveau chaque scan.
// ⚠️ Si SimulationModeActive est déjà TRUE au boot (aucun front observé), Sim*Active reste
// FALSE → routage HwReal. Activer la simulation par un vrai front OFF→ON après démarrage.
// Cohérent pour les 4 domaines (Winch/Translation/Operator/Safety).
IF SimulationModeRise.Q THEN
    GVL_Simulation.SimWinchActive       := TRUE;
    GVL_Simulation.SimTranslationActive := TRUE;
    GVL_Simulation.SimOperatorActive    := TRUE;
    GVL_Simulation.SimSafetyActive      := TRUE;
END_IF;

IF SimulationModeFall.Q THEN
    // 🧪 Desactivation des aiguillages + reset des stimuli de simulation (front descendant)
    GVL_Simulation.SimWinchActive       := FALSE;
    GVL_Simulation.SimTranslationActive := FALSE;
    GVL_Simulation.SimOperatorActive    := FALSE;
    GVL_Simulation.SimSafetyActive      := FALSE;
    GVL_Simulation.SimM3SensorsWordOverrideActive := FALSE;
    GVL_Simulation.SimM3SensorsWord := 16#07;
    GVL_Simulation.SimJoystickLeft_Rev_TREMIE_Active := FALSE;
    GVL_Simulation.SimJoystickRight_Fwd_MAINT_Active := FALSE;
    GVL_Simulation.SimJoystickFwd_Up_Close_Active := FALSE;
    GVL_Simulation.SimJoystickRev_Down_Open_Active := FALSE;
    GVL_Simulation.SimJoystickRawX := 5000;
    GVL_Simulation.SimJoystickRawY := 5000;
    GVL_Simulation.SimJoystickRawButton := FALSE;
    GVL_Simulation.SimJoystickOvershoot_Active := FALSE;
    GVL_Simulation.SimJoystickBagotement_Active := FALSE;
    GVL_Simulation.SimEncoderSpeedFactor := 1.0;
    GVL_Simulation.SimTopPositionActive := FALSE;
    GVL_Simulation.SimChainOk := FALSE; // Chaîne AU ouverte à la ré-entrée (on n'a pas armé)
    GVL_Simulation.SimSyncDeviationInjectM1 := FALSE;
    GVL_Simulation.SimSyncDeviationInjectM2 := FALSE;
    GVL_Simulation.SimSyncDeviationOffset_M := 0.5;
    GVL_Simulation.SimKoboldContactValue := FALSE;
END_IF;

// 🔀 Aiguillages de source uniques par domaine
WinchInputSourceSimulated       := GVL_Simulation.SimulationModeActive AND GVL_Simulation.SimWinchActive;
TranslationInputSourceSimulated := GVL_Simulation.SimulationModeActive AND GVL_Simulation.SimTranslationActive;
OperatorInputSourceSimulated    := GVL_Simulation.SimulationModeActive AND GVL_Simulation.SimOperatorActive;
MachineInputSourceSimulated     := GVL_Simulation.SimulationModeActive AND GVL_Simulation.SimSafetyActive;
{endregion}

{region "§1 Acquisition brute — HwReal"}
// === 📥 §1 ACQUISITION BRUTE MATÉRIELLE (HwReal) ===

// Winch M1 / M2 et codeurs
HwReal.Winch.M1_ContactorsReleased_DI := M1_ContactorsReleased_DI;
HwReal.Winch.M1_ThermalOk_DI          := M1_ThermalOk_DI;
HwReal.Winch.M1_BrakeIsOpen_DI        := M1_BrakeIsOpen_DI;

HwReal.Winch.M2_ContactorsReleased_DI := M2_ContactorsReleased_DI;
HwReal.Winch.M2_ThermalOk_DI          := M2_ThermalOk_DI;
HwReal.Winch.M2_BrakeIsOpen_DI        := M2_BrakeIsOpen_DI;

HwReal.Winch.M1M2_TopPositionFree_DI  := M1M2_TopPositionFree_DI;
HwReal.Winch.M2_TensionedCable_DI     := M2_TensionedCable_DI;

HwReal.Winch.COD1_PosValue            := COD1_PosValue;
HwReal.Winch.COD1_Alarms              := COD1_Alarms;
HwReal.Winch.COD1_Warnings            := COD1_Warnings;
HwReal.Winch.COD1_DeviceState         := COD1_CODEUR.GetDeviceState();

HwReal.Winch.COD2_PosValue            := COD2_PosValue;
HwReal.Winch.COD2_Alarms              := COD2_Alarms;
HwReal.Winch.COD2_Warnings            := COD2_Warnings;
HwReal.Winch.COD2_DeviceState         := COD2_CODEUR.GetDeviceState();

// Translation M3 et variateur AC600
HwReal.Translation.M3_PosTremie_DI      := M3_PosTremie_DI;
HwReal.Translation.M3_PosPV_DI          := M3_PosPV_DI;
HwReal.Translation.M3_PosPVP2_DI        := M3_PosPVP2_DI;
HwReal.Translation.M3_PosP1_DI          := M3_PosP1_DI;
HwReal.Translation.M3_PosMaintenance_DI := M3_PosMaintenance_DI;
HwReal.Translation.M3_BrakeIsOpen_DI    := M3_BrakeIsOpen_DI;
HwReal.Translation.M3_ThermalOK_DI       := M3_ThermalOK_DI;
HwReal.Translation.M3_StatusWord        := M3_StatusWord;
HwReal.Translation.M3_ActualFrequencyHz := M3_ActualFrequencyHz;
HwReal.Translation.AC600_DeviceState    := AC600_ECAT_Drive.GetDeviceState();

// Opérateur / Joystick / bus CANopen
HwReal.Operator.JoyXRaw_ANA1      := JoyXRaw_ANA1;
HwReal.Operator.JoyYRaw_ANA2      := JoyYRaw_ANA2;
HwReal.Operator.JoyBtnRaw         := JoyBtnRaw;
HwReal.Operator.CanBusState       := CANbus.GetBusState();
HwReal.Operator.JOY1_DeviceState  := JOY1_JOYSTICK_MCB560_CO4201A.GetDeviceState();

// Sécurités / Communs Machine
HwReal.Machine.PowerContactorEngaged_DI   := PowerContactorEngaged_DI;
HwReal.Machine.EmergencyChainClosed_DI    := EmergencyChainClosed_DI;
HwReal.Machine.PhaseRotationOk_DI         := PhaseRotationOk_DI;
HwReal.Machine.M1_M2_M3_BrakeThermalOk_DI  := M1_M2_M3_BrakeThermalOk_DI;
HwReal.Machine.M1_M2_KoboldBottomTouch_DI  := M1_M2_KoboldBottomTouch_DI;
HwReal.Machine.HydraulicThermalOk_DI       := HydraulicThermalOk_DI;
HwReal.Machine.ConveyorInfeedReady_DI      := ConveyorInfeedReady_DI;
HwReal.Machine.TremieFull_OR_GateRaised_DI := TremieFull_OR_GateRaised_DI; // 🚧 Déclaré, non consommé — interlock trémie à câbler
{endregion}

{region "§1bis Diagnostic modules E/S"}
// === 🩺 §1bis DIAGNOSTIC MODULES E/S ===
// 🩺 Diagnostic carte des 5 modules d'E/S physiques (AF06 §3bis).
// GetDeviceState() = RUNNING => module opérationnel. Si la simulation globale/machine est active,
// les cartes physiques absentes sont simulées OK pour permettre le fonctionnement banc.
IF MachineInputSourceSimulated OR GVL_IHM.Network.Bypass.Global OR GVL_IHM.Network.Bypass.InputModules THEN
    Data.InputModules.LocalDigitalIoOk := TRUE;
    Data.InputModules.Vh0800EndOk      := TRUE;
    Data.InputModules.Vh0808EtpOk      := TRUE;
    Data.InputModules.Vh0008ErOk       := TRUE;
    Data.InputModules.Vh0008Er1Ok      := TRUE;
ELSE
    Data.InputModules.LocalDigitalIoOk := (Local_Digital_IO.GetDeviceState() = DEVICE_STATE.RUNNING);
    Data.InputModules.Vh0800EndOk      := (VH_0800END.GetDeviceState() = DEVICE_STATE.RUNNING);
    Data.InputModules.Vh0808EtpOk      := (VH_0808ETP.GetDeviceState() = DEVICE_STATE.RUNNING);
    Data.InputModules.Vh0008ErOk       := (VH_0008ER.GetDeviceState() = DEVICE_STATE.RUNNING);
    Data.InputModules.Vh0008Er1Ok      := (VH_0008ER_1.GetDeviceState() = DEVICE_STATE.RUNNING);
END_IF;
Data.InputModules.Fault := NOT (Data.InputModules.LocalDigitalIoOk AND Data.InputModules.Vh0800EndOk AND Data.InputModules.Vh0808EtpOk AND Data.InputModules.Vh0008ErOk AND Data.InputModules.Vh0008Er1Ok);
{endregion}

{region "§1ter Diagnostic reseaux (CANopen + EtherCAT)"}
// === 🔌 §1ter DIAGNOSTIC RÉSEAUX (CANopen + EtherCAT) ===
// 🔌 Diagnostics reseau produits ICI (rang 02) car consommes par PRG_02 (joystick,
// codeurs) et par les PRG 04/05 — producteur avant consommateur (AF02 §4).
instDiagCanOpen(
    Enable                 := TRUE,
    Reset                  := PRG_07_Supervision.FaultMachineReset_IHM,
    CANbusStateRaw         := HwReal.Operator.CanBusState,
    DeviceJoystickStateRaw := HwReal.Operator.JOY1_DeviceState,
    SimBypassActive        := GVL_Simulation.SimulationModeActive AND GVL_Simulation.SimOperatorActive,
    NetworkBypassActive    := GVL_IHM.Network.Bypass.Global,
    CanBusBypassActive     := GVL_IHM.Network.Bypass.BusCanOpen,
    JoystickBypassActive   := GVL_IHM.Network.Bypass.Joystick
);
instDiagEthercat(
    Enable                   := TRUE,
    Reset                    := PRG_07_Supervision.FaultMachineReset_IHM,
    DeviceVariateurStateRaw  := HwReal.Translation.AC600_DeviceState,
    DeviceVariateurSimBypass := GVL_Simulation.SimulationModeActive AND GVL_Simulation.SimTranslationActive,
    DeviceEncoderM1StateRaw  := HwReal.Winch.COD1_DeviceState,
    DeviceEncoderM1SimBypass := GVL_Simulation.SimulationModeActive AND GVL_Simulation.SimWinchActive,
    DeviceEncoderM2StateRaw  := HwReal.Winch.COD2_DeviceState,
    DeviceEncoderM2SimBypass := GVL_Simulation.SimulationModeActive AND GVL_Simulation.SimWinchActive,
    NetworkBypassActive      := GVL_IHM.Network.Bypass.Global,
    EcatBusBypassActive      := GVL_IHM.Network.Bypass.BusEthercat,
    VariateurBypassActive    := GVL_IHM.Network.Bypass.VariateurM3,
    EncoderM1BypassActive    := GVL_IHM.Network.Bypass.EncoderM1,
    EncoderM2BypassActive    := GVL_IHM.Network.Bypass.EncoderM2
);

// 📤 Publication du sous-bus diagnostics réseaux
Data.Network.CanOpenMaster   := instDiagCanOpen.DeviceCanOpenMaster;
Data.Network.Joystick        := instDiagCanOpen.DeviceJoystick;
Data.Network.EthercatMaster  := instDiagEthercat.DeviceEthercatMaster;
Data.Network.EncoderM1       := instDiagEthercat.DeviceEncoderM1;
Data.Network.EncoderM2       := instDiagEthercat.DeviceEncoderM2;
Data.Network.DriveM3         := instDiagEthercat.DeviceVariateur;
{endregion}

{region "§2 Simulation et aiguillage — HwIn"}
// === 🎭 §2 SIMULATION & AIGUILLAGE (HwIn) ===

instSimBench(
    Enable                   := GVL_Simulation.SimulationModeActive,
    M1_RelayFwd              := PRG_06_Outputs.Data.M1RelayFwd,
    M1_RelayRev              := PRG_06_Outputs.Data.M1RelayRev,
    M1_SpeedContactor_1      := PRG_06_Outputs.Data.M1SpeedContactor1,
    M1_SpeedContactor_2      := PRG_06_Outputs.Data.M1SpeedContactor2,
    M1_SpeedContactor_3      := PRG_06_Outputs.Data.M1SpeedContactor3,
    M1_SpeedContactor_4      := PRG_06_Outputs.Data.M1SpeedContactor4,
    M1_SpeedCmd_Pct          := PRG_04_Treuils_Benne.Data.M1LogicRequestSpeedCmd_Pct,
    M1_StepNumber            := PRG_04_Treuils_Benne.Data.WinchM1State.StepNumber,
    M1_PresetTriggerCmd      := instEncoderM1.HwOut.PresetTriggerCmd,
    M1_PresetValueOut        := instEncoderM1.HwOut.PresetValueOut,
    M1_BrakeCmd              := PRG_06_Outputs.Data.M1BrakeCmd,
    M2_RelayFwd              := PRG_06_Outputs.Data.M2RelayFwd,
    M2_RelayRev              := PRG_06_Outputs.Data.M2RelayRev,
    M2_SpeedContactor_1      := PRG_06_Outputs.Data.M2SpeedContactor1,
    M2_SpeedContactor_2      := PRG_06_Outputs.Data.M2SpeedContactor2,
    M2_SpeedContactor_3      := PRG_06_Outputs.Data.M2SpeedContactor3,
    M2_SpeedContactor_4      := PRG_06_Outputs.Data.M2SpeedContactor4,
    M2_SpeedCmd_Pct          := PRG_04_Treuils_Benne.Data.M2LogicRequestSpeedCmd_Pct,
    M2_StepNumber            := PRG_04_Treuils_Benne.Data.WinchM2State.StepNumber,
    M2_PresetTriggerCmd      := instEncoderM2.HwOut.PresetTriggerCmd,
    M2_PresetValueOut        := instEncoderM2.HwOut.PresetValueOut,
    M2_BrakeCmd              := PRG_06_Outputs.Data.M2BrakeCmd,
    // 🧪 Simulation M3 — FIDÉLITÉ : le modèle ne doit progresser QUE quand la
    // vraie machine commande réellement (sortie PRG_06, post-interlock), pas sur la
    // commande brute (sinon le modèle outrepasse butées/limites). Les deux bits explicites
    // sont décodés depuis le mot effectivement appliqué au variateur.
    M3_ReqTremie            := M3_CommandWord = 1,
    M3_ReqMaintenance       := M3_CommandWord = 2,
    M3_SpeedCmd_Pct          := LIMIT(0.0,
                                      (WORD_TO_UINT(M3_SetpointFrequencyHz) / 100.0)
                                      / GVL_PERSISTENT._TranslationMaxFreq_Hz * 100.0,
                                      100.0),
    M3_BrakeCmd              := PRG_06_Outputs.Data.TranslationBrakeCmd,
    PowerKeepAlive_A         := PRG_06_Outputs.Data.PowerKeepAliveACmd,
    PowerKeepAlive_B         := PRG_06_Outputs.Data.PowerKeepAliveBCmd,
    // 🧪 Simulation uniquement : l'état étape 5 sécurise le transfert même si la sortie
    // inter-POU ArmPulse est observée avec un cycle de retard dans la tâche.
    EmergencyArming_RQ       := PRG_06_Outputs.Data.EmergencyArmingCmd
                                 OR (PRG_06_Outputs.EmergencyState.Step = 5),
    // 🧪 Test de redondance AU : la simulation ouvre la boucle (SimChainOk=FALSE) pendant
    // le test A/B pour que le FB AU valide la chute de chaîne (cercle cassé, voir FB_Sim_Safety).
    TestCutActive            := PRG_06_Outputs.Data.TestCutActive,
    // 🛑 Coupure métier : la simulation ouvre la chaîne AU (arrêt d'urgence) sur PowerCutOffRequest.
    PowerCutOffRequest       := PRG_06_Outputs.Data.PowerCutOffRequest,
    // 🧪 Contrôle granulaire de la chaîne AU : bit opérateur (GVL_Simulation.SimChainOk).
    SimChainOkBit            := GVL_Simulation.SimChainOk,
    SimEncoderSpeedFactor    := GVL_Simulation.SimEncoderSpeedFactor,
    SimTopPositionActive     := GVL_Simulation.SimTopPositionActive,
    SimSyncDeviationInjectM1 := GVL_Simulation.SimSyncDeviationInjectM1,
    SimSyncDeviationInjectM2 := GVL_Simulation.SimSyncDeviationInjectM2,
    SimSyncDeviationOffset_M := GVL_Simulation.SimSyncDeviationOffset_M,
    SimM3SensorsWordOverrideActive := GVL_Simulation.SimM3SensorsWordOverrideActive,
    SimM3SensorsWord               := GVL_Simulation.SimM3SensorsWord,
    SimJoystickLeft_Rev_TREMIE_Active  := GVL_Simulation.SimJoystickLeft_Rev_TREMIE_Active,
    SimJoystickRight_Fwd_MAINT_Active  := GVL_Simulation.SimJoystickRight_Fwd_MAINT_Active,
    SimJoystickFwd_Up_Close_Active     := GVL_Simulation.SimJoystickFwd_Up_Close_Active,
    SimJoystickRev_Down_Open_Active    := GVL_Simulation.SimJoystickRev_Down_Open_Active,
    SimJoystickRawX                    := GVL_Simulation.SimJoystickRawX,
    SimJoystickRawY                    := GVL_Simulation.SimJoystickRawY,
    SimJoystickRawButton               := GVL_Simulation.SimJoystickRawButton,
    SimJoystickOvershoot_Active        := GVL_Simulation.SimJoystickOvershoot_Active,
    SimJoystickBagotement_Active       := GVL_Simulation.SimJoystickBagotement_Active,
    SimKoboldContactValue    := GVL_Simulation.SimKoboldContactValue,
    BtnEmergencyStop         := GVL_IHM.Emergency.Cmd.BtnEmergencyCutOff,
    HwReal                   := HwReal,
    RawPosM1                 := _SimEncoderRawPosM1,
    RawPosM2                 := _SimEncoderRawPosM2
);

// Exposition de l'image de simulation produite par le banc
HwSim.Winch       := instSimBench.Winch;
HwSim.Translation := instSimBench.Translation;
HwSim.Operator    := instSimBench.Operator;
HwSim.Machine     := instSimBench.Machine;

// 🔀 Détection de bascule de source (réel/simu) par domaine — impulsion 1 cycle.
// Même pattern que Winch : mémoire Previous*InputSourceSimulated + comparaison.
IF NOT WinchInputSourceInitialized THEN
    PreviousWinchInputSourceSimulated := WinchInputSourceSimulated;
    WinchInputSourceInitialized := TRUE;
    Data.InputSource.WinchInputSourceChanged := FALSE;
ELSE
    Data.InputSource.WinchInputSourceChanged := (WinchInputSourceSimulated <> PreviousWinchInputSourceSimulated);
    PreviousWinchInputSourceSimulated := WinchInputSourceSimulated;
END_IF;

IF NOT TranslationInputSourceInitialized THEN
    PreviousTranslationInputSourceSimulated := TranslationInputSourceSimulated;
    TranslationInputSourceInitialized := TRUE;
    Data.InputSource.TranslationInputSourceChanged := FALSE;
ELSE
    Data.InputSource.TranslationInputSourceChanged := (TranslationInputSourceSimulated <> PreviousTranslationInputSourceSimulated);
    PreviousTranslationInputSourceSimulated := TranslationInputSourceSimulated;
END_IF;

IF NOT OperatorInputSourceInitialized THEN
    PreviousOperatorInputSourceSimulated := OperatorInputSourceSimulated;
    OperatorInputSourceInitialized := TRUE;
    Data.InputSource.OperatorInputSourceChanged := FALSE;
ELSE
    Data.InputSource.OperatorInputSourceChanged := (OperatorInputSourceSimulated <> PreviousOperatorInputSourceSimulated);
    PreviousOperatorInputSourceSimulated := OperatorInputSourceSimulated;
END_IF;

IF NOT MachineInputSourceInitialized THEN
    PreviousMachineInputSourceSimulated := MachineInputSourceSimulated;
    MachineInputSourceInitialized := TRUE;
    Data.InputSource.MachineInputSourceChanged := FALSE;
ELSE
    Data.InputSource.MachineInputSourceChanged := (MachineInputSourceSimulated <> PreviousMachineInputSourceSimulated);
    PreviousMachineInputSourceSimulated := MachineInputSourceSimulated;
END_IF;

// 🔧 SEL(G, IN0, IN1) : brique standard IEC 61131-3, retourne IN1 si G=TRUE, IN0 sinon
// (AF_Partie-03 §1 : composer l'existant avant réimplémentation) — remplace les 4 IF/ELSE
// compactés qui cassaient le générateur ST→LD (CODE_QUALITY_STANDARDS.md §11).
// Utilisation explicite de HwSim.* et des 4 variables de sélection par domaine.
HwIn.Winch       := SEL(WinchInputSourceSimulated, HwReal.Winch, HwSim.Winch);
HwIn.Translation := SEL(TranslationInputSourceSimulated, HwReal.Translation, HwSim.Translation);
HwIn.Operator    := SEL(OperatorInputSourceSimulated, HwReal.Operator, HwSim.Operator);
HwIn.Machine     := SEL(MachineInputSourceSimulated, HwReal.Machine, HwSim.Machine);
{endregion}


{region "§3 Traitement joystick"}
// === 🕹️ §3 TRAITEMENT JOYSTICK ===

// La table des paliers est une source unique commune M1/M2. Les autres
// reglages restent ceux propres au joystick et a son pont IHM/persistant.
JoystickCfgEffective := GVL_PERSISTENT._JoystickCfgPersist;
JoystickCfgEffective.SpeedStepTable := GVL_PERSISTENT._WinchSpeedStepTable;

instJoystick(
    Enable                    := TRUE,
    Reset                     := PRG_07_Supervision.FaultMachineReset_IHM,
    // 🚨 ArmingPermit = ENTRÉE du joystick (vue joystick), alimentée de n'importe où.
    // 🔧 Producteur = PRG_04_Treuils_Benne (combiné interlock benne) via le bus Data.
    //    TRUE = armement autorisé (polarité positive NC-100).
    ArmingPermit              := PRG_04_Treuils_Benne.Data.ArmingPermit,
    BusCanOpenOP              := instDiagCanOpen.DeviceCanOpenMaster,
    JoystickOP                := instDiagCanOpen.DeviceJoystick,
    RawX                      := HwIn.Operator.JoyXRaw_ANA1,
    RawY                      := HwIn.Operator.JoyYRaw_ANA2,
    RawButton                 := HwIn.Operator.JoyBtnRaw,
    Calibrate                 := GVL_IHM.JOY1Joystick.Cmd.Calibrate,
    Cfg                       := JoystickCfgEffective,
    NeutralXMem               := _JoystickNeutralX,
    NeutralYMem               := _JoystickNeutralY
);

// 📤 Publication du sous-bus joystick qualifié
Data.Joystick.AxisX              := instJoystick.AxisCmdX;
Data.Joystick.AxisY              := instJoystick.AxisCmdY;
Data.Joystick.DeadmanArmed       := instJoystick.DeadmanArmed;
Data.Joystick.AtNeutralXY        := instJoystick.AtNeutralXY;
Data.Joystick.ArmingPermitDenied := instJoystick.ArmingPermitDenied;
Data.Joystick.Ready              := instJoystick.Ready;
Data.Joystick.Fault              := instJoystick.Fault;
Data.Joystick.NeutralXAct        := instJoystick.NeutralXAct;
Data.Joystick.NeutralYAct        := instJoystick.NeutralYAct;
{endregion}

{region "§4 Codeurs et homing — M1/M2"}
// === 🧲 §4 CODEURS & HOMING (M1 / M2) ===

// ── TREUIL M1 (Retenue) ──
// Facade codeur complete : Abs→Homing→Scale→Safety→Reliability→Speed.
// L'autorisation de homing est calculee ici (mode + treuil selectionne).
// Frontiere hardware remplie avant l'appel (le bus Hw est passe en entier).
(* Centralise les fronts IHM avant les deux facades codeur. La polarite du DI
   est explicite : Free=TRUE signifie capteur haut non atteint. *)
MachineHomingM1Status.HomedAndReliable := Data.EncoderM1.HomedAndReliable;
MachineHomingM1Status.HomingBusy       := Data.EncoderM1.Measurement.HomingLifecycle.Busy;
MachineHomingM1Status.HomingDone       := Data.EncoderM1.Measurement.HomingLifecycle.Done;
MachineHomingM1Status.HomingError      := Data.EncoderM1.Measurement.HomingFault.Error;
MachineHomingM2Status.HomedAndReliable := Data.EncoderM2.HomedAndReliable;
MachineHomingM2Status.HomingBusy       := Data.EncoderM2.Measurement.HomingLifecycle.Busy;
MachineHomingM2Status.HomingDone       := Data.EncoderM2.Measurement.HomingLifecycle.Done;
MachineHomingM2Status.HomingError      := Data.EncoderM2.Measurement.HomingFault.Error;
MachineHomingMechanicalStopOk := HwIn.Winch.M1_ContactorsReleased_DI AND NOT HwIn.Winch.M1_BrakeIsOpen_DI
                                 AND (ABS(Data.EncoderM1.Measurement.Speed_Mps) < 0.02)
                                 AND HwIn.Winch.M2_ContactorsReleased_DI AND NOT HwIn.Winch.M2_BrakeIsOpen_DI
                                 AND (ABS(Data.EncoderM2.Measurement.Speed_Mps) < 0.02);

// Les confirmations benne restent des commandes IHM N2 dédiées : elles
// homent matériellement M2 sur la géométrie observée, sans ré-homer M1.
BucketReferenceOpenEdge(CLK := GVL_IHM.M2TreuilBenne.Bucket.Cmd.BtnConfirmOpenPos);
BucketReferenceCloseEdge(CLK := GVL_IHM.M2TreuilBenne.Bucket.Cmd.BtnConfirmClosePos);
BucketReferenceRequested := (BucketReferenceOpenEdge.Q XOR BucketReferenceCloseEdge.Q)
                          AND (PRG_03_Modes_Cycle.Data.Auth.Mode = E_Mode.MAINT_N2)
                          AND MachineHomingMechanicalStopOk;
IF BucketReferenceOpenEdge.Q THEN
    BucketReferenceTargetM := instEncoderM1.Measurement.CablePosM;
ELSIF BucketReferenceCloseEdge.Q THEN
    BucketReferenceTargetM := instEncoderM1.Measurement.CablePosM + _BucketCfgPersist.Config.OffsetCloseM;
END_IF;

MachineHomingCfg.CfgTopHomingTarget_M := _WinchM1CfgPersist.CfgTopSensorPos_M;
MachineHomingCfg.CfgOffsetOpen_M      := _BucketCfgPersist.Config.OffsetOpenM;
MachineHomingCfg.CfgOffsetClose_M     := _BucketCfgPersist.Config.OffsetCloseM;
MachineHomingCfg.Initialized          := TRUE;
instMachineHomingCycle(
    Enable                     := TRUE,
    Reset                      := PRG_07_Supervision.FaultMachineReset_IHM,
    Mode                       := PRG_03_Modes_Cycle.Data.Auth.Mode,
    TopPositionSensor          := NOT HwIn.Winch.M1M2_TopPositionFree_DI,
    WinchesMechanicallyStopped  := MachineHomingMechanicalStopOk,
    M1Status                   := MachineHomingM1Status,
    M2Status                   := MachineHomingM2Status,
    BucketOffsetValid          := PRG_04_Treuils_Benne.Data.BucketState.MechState.ActiveOffsetValid,
    // Permis operateur maintenu (meme source que l'arbitrage joystick) : sens montee = manche
    // tire (Y+), sens descente = manche pousse (Y-) ; ref. baseline continuite C1.
    DeadmanArmed               := Data.Joystick.DeadmanArmed,
    JoystickDeflected          := NOT Data.Joystick.AtNeutralXY,
    JoystickPull               := Data.Joystick.AxisY.DirectionPositive,
    JoystickPush               := Data.Joystick.AxisY.DirectionNegative,
    // BP validation (motif 3 appuis) : source BP joystick a mapper en acquisition HW.
    // En attente : forcable en Watch CODESYS pour la MES banc.
    BtnValidation              := FALSE,
    Cfg                        := MachineHomingCfg
);
Data.MachineHoming.Homed            := instMachineHomingCycle.MachineHomed;
Data.MachineHoming.SetPosBucketOpen := instMachineHomingCycle.BucketCommit.CommitOpen;
Data.MachineHoming.SetPosBucketClose := instMachineHomingCycle.BucketCommit.CommitClose;
Data.MachineHoming.Active           := instMachineHomingCycle.MachineHomingActive;
Data.MachineHoming.HomingLoss       := instMachineHomingCycle.MachineHomingLossSafeStop;
Data.MachineHoming.Step             := TO_INT(instMachineHomingCycle.MachineHomingStep);
Data.MachineHoming.Instruction      := instMachineHomingCycle.MachineHomingInstruction;
Data.MachineHoming.Failed           := instMachineHomingCycle.MachineHomingFailed;
Data.MachineHoming.SeqStep          := TO_INT(instMachineHomingCycle.MachineHomingSeqStep);
Data.MachineHoming.M3Locked         := instMachineHomingCycle.M3Locked;
Data.MachineHoming.CmdWinchM1       := instMachineHomingCycle.CmdWinchM1;
Data.MachineHoming.CmdWinchM2       := instMachineHomingCycle.CmdWinchM2;
Data.MachineHoming.CmdBucketOpen    := instMachineHomingCycle.CmdBucketOpen;
Data.MachineHoming.CmdBucketClose   := instMachineHomingCycle.CmdBucketClose;
HwInM1.RawPosIn          := HwIn.Winch.COD1_PosValue;
HwInM1.AlarmsIn          := HwIn.Winch.COD1_Alarms;
HwInM1.WarningsIn        := HwIn.Winch.COD1_Warnings;
HwInM1.SlaveOperational  := instDiagEthercat.DeviceEncoderM1.Operational;
HwInM1.PresetStatusBit    := FALSE;
instEncoderM1(
    Enable                := TRUE,
    Reset                 := PRG_07_Supervision.FaultMachineReset_IHM,
    HomingPermit          := (((PRG_03_Modes_Cycle.Data.Auth.Mode = E_Mode.MAINT_N1 OR PRG_03_Modes_Cycle.Data.Auth.Mode = E_Mode.MAINT_N2)
                               AND (PRG_03_Modes_Cycle.Data.Auth.JoystickWinchSelectArbitrated <> 2)
                               AND (MachineHomingMechanicalStopOk OR (NOT GVL_IHM.M1TreuilRetenue.Cmd.BtnHomingAtZero
                                                                       AND NOT HwIn.Winch.M1M2_TopPositionFree_DI)))
                              OR instMachineHomingCycle.M1Demand.HomeReq),
    HomingAtTargetM       := GVL_IHM.M1TreuilRetenue.Cmd.BtnHome
                             OR GVL_IHM.M1TreuilRetenue.Cmd.BtnHomingAtZero
                             OR instMachineHomingCycle.M1Demand.HomeReq,
    HomingAtZero          := GVL_IHM.M1TreuilRetenue.Cmd.BtnHomingAtZero,
    ConfirmCoherence      := GVL_IHM.M1TreuilRetenue.Cmd.BtnConfirmCoherence,
    CfgHomingTargetM      := SEL(GVL_IHM.M1TreuilRetenue.Cmd.BtnHomingAtZero,
                                 _WinchM1CfgPersist.CfgTopSensorPos_M, 0.0),
    CfgTopSensorPosM      := _WinchM1CfgPersist.CfgTopSensorPos_M,
    UseDynamicTarget      := FALSE,
    DynamicHomingTargetM  := 0.0,
    TopPositionSensor     := NOT HwIn.Winch.M1M2_TopPositionFree_DI,
    HwIn                  := HwInM1,
    PointsPerRev          := ENCODER_POINTS_PER_REV,
    CableM_PerRev         := WINCH_CABLE_M_PER_REV,
    Cfg                   := GVL_IHM.Commun.EncoderCfg,
    BypassGlobal          := GVL_IHM.M1TreuilRetenue.Bypass.Global,
    Calib                 := _CalibM1
);

// 📤 Publication de la façade codeur M1 qualifiée
Data.EncoderM1.Measurement              := instEncoderM1.Measurement;
Data.EncoderM1.Ready                    := instEncoderM1.Ready;
Data.EncoderM1.Fault                    := instEncoderM1.Fault;
Data.EncoderM1.Homed                    := instEncoderM1.Homed;
Data.EncoderM1.HomingSuspect            := instEncoderM1.HomingSuspect;
Data.EncoderM1.EncoderFault             := instEncoderM1.EncoderFault;
Data.EncoderM1.HomedAndReliable         := instEncoderM1.HomedAndReliable;
Data.EncoderM1.PresetConfirmationFailed := instEncoderM1.PresetConfirmationFailed;
Data.EncoderM1.HwOut                    := instEncoderM1.HwOut;
COD1_PresettTrigCmd := instEncoderM1.HwOut.PresetTriggerCmd;
COD1_CodeSeqTrigCmd := instEncoderM1.HwOut.CodeSeqTriggerCmd;
COD1_PresetValue    := instEncoderM1.HwOut.PresetValueOut;

// ── TREUIL M2 (Benne) ──
// Ordre POO : synchronisation benne, puis Homing, puis facade.

// Frontiere hardware remplie avant l'appel (le bus Hw est passe en entier).
HwInM2.RawPosIn          := HwIn.Winch.COD2_PosValue;
HwInM2.AlarmsIn          := HwIn.Winch.COD2_Alarms;
HwInM2.WarningsIn        := HwIn.Winch.COD2_Warnings;
HwInM2.SlaveOperational  := instDiagEthercat.DeviceEncoderM2.Operational;
HwInM2.PresetStatusBit    := FALSE;
instEncoderM2(
    Enable                := TRUE,
    Reset                 := PRG_07_Supervision.FaultMachineReset_IHM,
    HomingPermit          := (((PRG_03_Modes_Cycle.Data.Auth.Mode = E_Mode.MAINT_N1 OR PRG_03_Modes_Cycle.Data.Auth.Mode = E_Mode.MAINT_N2)
                               AND (PRG_03_Modes_Cycle.Data.Auth.JoystickWinchSelectArbitrated <> 1)
                               AND (MachineHomingMechanicalStopOk OR (NOT GVL_IHM.M2TreuilBenne.Cmd.BtnHomingAtZero
                                                                       AND NOT HwIn.Winch.M1M2_TopPositionFree_DI)))
                              OR instMachineHomingCycle.M2Demand.HomeReq),
    HomingAtTargetM       := GVL_IHM.M2TreuilBenne.Cmd.BtnHome
                             OR GVL_IHM.M2TreuilBenne.Cmd.BtnHomingAtZero
                             OR BucketReferenceRequested
                             OR instMachineHomingCycle.M2Demand.HomeReq,
    HomingAtZero          := GVL_IHM.M2TreuilBenne.Cmd.BtnHomingAtZero,
    ConfirmCoherence      := GVL_IHM.M2TreuilBenne.Cmd.BtnConfirmCoherence,
    CfgHomingTargetM      := SEL(GVL_IHM.M2TreuilBenne.Cmd.BtnHomingAtZero,
                                 _WinchM2CfgPersist.CfgTopSensorPos_M, 0.0),
    CfgTopSensorPosM      := _WinchM2CfgPersist.CfgTopSensorPos_M,
    UseDynamicTarget      := BucketReferenceRequested OR instMachineHomingCycle.M2Demand.UseDynamicTarget,
    DynamicHomingTargetM  := SEL(BucketReferenceRequested,
                                 instMachineHomingCycle.M2Demand.DynamicTarget_M, BucketReferenceTargetM),
    TopPositionSensor     := NOT HwIn.Winch.M1M2_TopPositionFree_DI,
    HwIn                  := HwInM2,
    PointsPerRev          := ENCODER_POINTS_PER_REV,
    CableM_PerRev         := WINCH_CABLE_M_PER_REV,
    Cfg                   := GVL_IHM.Commun.EncoderCfg,
    BypassGlobal          := GVL_IHM.M2TreuilBenne.Bypass.Global,
    Calib                 := _CalibM2
);

// 📤 Publication de la façade codeur M2 qualifiée
Data.EncoderM2.Measurement              := instEncoderM2.Measurement;
Data.EncoderM2.Ready                    := instEncoderM2.Ready;
Data.EncoderM2.Fault                    := instEncoderM2.Fault;
Data.EncoderM2.Homed                    := instEncoderM2.Homed;
Data.EncoderM2.HomingSuspect            := instEncoderM2.HomingSuspect;
Data.EncoderM2.EncoderFault             := instEncoderM2.EncoderFault;
Data.EncoderM2.HomedAndReliable         := instEncoderM2.HomedAndReliable;
Data.EncoderM2.PresetConfirmationFailed := instEncoderM2.PresetConfirmationFailed;
Data.EncoderM2.HwOut                    := instEncoderM2.HwOut;
COD2_PresettTrigCmd := instEncoderM2.HwOut.PresetTriggerCmd;
COD2_CodeSeqTrigCmd := instEncoderM2.HwOut.CodeSeqTriggerCmd;
COD2_PresetValue    := instEncoderM2.HwOut.PresetValueOut;
{endregion}

{region "§5 Retours variateur M3"}
// === ↔️ §5 RETOURS VARIATEUR M3 (décodage position migré vers PRG_05, AF-02 TBD §8 #5) ===

// 📊 Retours variateur M3 conditionnés (HwIn arbitré en §2)
Data.M3.StatusWord        := WORD_TO_UINT(HwIn.Translation.M3_StatusWord);
Data.M3.ActualFrequencyHz := HwIn.Translation.M3_ActualFrequencyHz;
{endregion}

{region "§6 Qualification globale du bus Data"}
// === 🛡️ §6 QUALIFICATION GLOBALE DU BUS DATA ===
// DataValid = TRUE uniquement si les modules E/S physiques et les bus réseaux sont opérationnels.
Data.DataValid := NOT Data.InputModules.Fault 
                  AND instDiagCanOpen.Ready 
                  AND instDiagEthercat.Ready;
{endregion}

{region "§1 Gate"}
// 🛑 1. GATE : Désactivation logique si Enable = FALSE
IF NOT Enable THEN
    Ready := FALSE;
    DeviceJoystick.State := E_Diag_State.DISABLED;
    DeviceJoystick.Online := FALSE;
    DeviceJoystick.Operational := FALSE;
    DeviceJoystick.Error := FALSE;
    DeviceJoystick.ErrorId := 16#0000;
    DeviceCanOpenMaster.State := E_Diag_State.DISABLED;
    DeviceCanOpenMaster.Online := FALSE;
    DeviceCanOpenMaster.Operational := FALSE;
    DeviceCanOpenMaster.Error := FALSE;
    DeviceCanOpenMaster.ErrorId := 16#0000;
    RETURN;
END_IF;

Ready := TRUE;
{endregion}

{region "§2 Interprétation valeurs brutes"}
// 🧮 2. INTERPRÉTATION DES VALEURS BRUTES
CANbusOnlineReal         := (CANbusStateRaw = 2);
DeviceJoystickOnlineReal := (DeviceJoystickStateRaw = DEVICE_STATE.RUNNING);

CANbusOnlineEff          := CANbusOnlineReal OR SimBypassActive OR NetworkBypassActive OR CanBusBypassActive;
DeviceJoystickOnlineEff  := DeviceJoystickOnlineReal OR SimBypassActive OR NetworkBypassActive OR JoystickBypassActive;
{endregion}

{region "§3 Reset front"}
// 🔑 3. RESET FRONT — Efface les défauts si la cause a disparu
ResetEdge(CLK := Reset);
IF ResetEdge.Q THEN
    IF (CANbusOnlineEff AND DeviceJoystickOnlineEff) THEN
        DeviceJoystick.ErrorId := 16#0000;
        DeviceJoystick.StateAtError := E_Diag_State.DISABLED;
    END_IF;
END_IF;
{endregion}

{region "§4 Diagnostic joystick"}
// 🔍 4. DIAGNOSTIC JOYSTICK
// Bit 0 : Perte de communication CAN
IF NOT CANbusOnlineEff THEN
    DeviceJoystick.ErrorId := DeviceJoystick.ErrorId OR 16#0001;  (* Perte liaison CAN joystick *)
ELSE
    DeviceJoystick.Online := TRUE;
    DeviceJoystick.ErrorId := DeviceJoystick.ErrorId AND 16#FFFE; (* Effacement auto si la liaison revient *)
END_IF;

// Bit 1 : Mode non-opérationnel (esclave CANopen en pré-op ou défaut)
IF NOT DeviceJoystickOnlineEff THEN
    DeviceJoystick.ErrorId := DeviceJoystick.ErrorId OR 16#0002;  (* Joystick pas opérationnel *)
    DeviceJoystick.Operational := FALSE;
ELSE
    DeviceJoystick.Operational := TRUE;
    DeviceJoystick.ErrorId := DeviceJoystick.ErrorId AND 16#FFFD; (* Effacement auto dès que RUNNING *)
END_IF;
{endregion}

{region "§5 Machine etat joystick"}
// 🚦 5. MACHINE D'ÉTAT JOYSTICK
IF DeviceJoystick.ErrorId <> 0 THEN
    DeviceJoystick.State := E_Diag_State.ERROR;
ELSIF NOT (DeviceJoystick.Online AND DeviceJoystick.Operational) THEN
    DeviceJoystick.State := E_Diag_State.INIT;
ELSIF (SimBypassActive OR NetworkBypassActive OR JoystickBypassActive) AND NOT (CANbusOnlineReal AND DeviceJoystickOnlineReal) THEN
    DeviceJoystick.State := E_Diag_State.SIMULATED;
ELSE
    DeviceJoystick.State := E_Diag_State.READY;
END_IF;
{endregion}

{region "§6 Sorties globales"}
// 📤 6. SORTIES GLOBALES
DeviceJoystick.Error := (DeviceJoystick.ErrorId <> 0);

DeviceCanOpenMaster.Operational := CANbusOnlineEff;
DeviceCanOpenMaster.Online := CANbusOnlineEff;
DeviceCanOpenMaster.Error := NOT CANbusOnlineEff;

IF NOT CANbusOnlineEff THEN
    DeviceCanOpenMaster.ErrorId := 16#0001;
    DeviceCanOpenMaster.State := E_Diag_State.ERROR;
    IF DeviceCanOpenMaster.StateAtError = E_Diag_State.DISABLED THEN
        DeviceCanOpenMaster.StateAtError := E_Diag_State.INIT;
    END_IF;
ELSIF (SimBypassActive OR NetworkBypassActive OR CanBusBypassActive) AND NOT CANbusOnlineReal THEN
    DeviceCanOpenMaster.ErrorId := 16#0000;
    DeviceCanOpenMaster.State := E_Diag_State.SIMULATED;
ELSE
    DeviceCanOpenMaster.ErrorId := 16#0000;
    DeviceCanOpenMaster.State := E_Diag_State.READY;
END_IF;
{endregion}

{region "§1 Gate de desactivation"}
// 🛑 1. GATE : Désactivation si Enable = FALSE
IF NOT Enable THEN
    Ready := FALSE;
    DeviceVariateur.State := E_Diag_State.DISABLED;
    DeviceEncoderM1.State := E_Diag_State.DISABLED;
    DeviceEncoderM2.State := E_Diag_State.DISABLED;
    DeviceVariateur.Online := FALSE;
    DeviceEncoderM1.Online := FALSE;
    DeviceEncoderM2.Online := FALSE;
    DeviceVariateur.Operational := FALSE;
    DeviceEncoderM1.Operational := FALSE;
    DeviceEncoderM2.Operational := FALSE;
    DeviceVariateur.Error := FALSE;
    DeviceEncoderM1.Error := FALSE;
    DeviceEncoderM2.Error := FALSE;
    DeviceEthercatMaster.State := E_Diag_State.DISABLED;
    DeviceEthercatMaster.Online := FALSE;
    DeviceEthercatMaster.Operational := FALSE;
    DeviceEthercatMaster.Error := FALSE;
    DeviceEthercatMaster.ErrorId := 16#0000;
    RETURN;
END_IF;

Ready := TRUE;

{endregion}

{region "§2 Interpretation etats bruts et bypass"}
// 🧮 2. INTERPRÉTATION DES VALEURS BRUTES
VariateurOnlineReal := (DeviceVariateurStateRaw = DEVICE_STATE.RUNNING);
EncoderM1OnlineReal := (DeviceEncoderM1StateRaw = DEVICE_STATE.RUNNING);
EncoderM2OnlineReal := (DeviceEncoderM2StateRaw = DEVICE_STATE.RUNNING);

VariateurBypass := DeviceVariateurSimBypass OR NetworkBypassActive OR VariateurBypassActive;
EncoderM1Bypass := DeviceEncoderM1SimBypass OR NetworkBypassActive OR EncoderM1BypassActive;
EncoderM2Bypass := DeviceEncoderM2SimBypass OR NetworkBypassActive OR EncoderM2BypassActive;

VariateurOnlineEff := VariateurOnlineReal OR VariateurBypass;
EncoderM1OnlineEff := EncoderM1OnlineReal OR EncoderM1Bypass;
EncoderM2OnlineEff := EncoderM2OnlineReal OR EncoderM2Bypass;

// 🔑 3. RESET FRONT
ResetEdge(CLK := Reset);

{endregion}

{region "§3 Diagnostic par equipement"}
// 🔍 4. DIAGNOSTIC VARIATEUR (AC600_ECAT_Drive / Translation M3)
DeviceVariateur.Online := VariateurOnlineEff;
DeviceVariateur.Operational := VariateurOnlineEff;

IF NOT DeviceVariateur.Online THEN
    DeviceVariateur.ErrorId := DeviceVariateur.ErrorId OR 16#0010;  (* Perte liaison physique variateur *)
ELSE
    DeviceVariateur.ErrorId := DeviceVariateur.ErrorId AND 16#FFEF; (* Effacement auto dès que RUNNING *)
END_IF;

// 🔍 5. DIAGNOSTIC ENCODEUR M1 (COD1_CODEUR / WinchM1)
DeviceEncoderM1.Online := EncoderM1OnlineEff;
DeviceEncoderM1.Operational := EncoderM1OnlineEff;

IF NOT DeviceEncoderM1.Online THEN
    DeviceEncoderM1.ErrorId := DeviceEncoderM1.ErrorId OR 16#0020;  (* Perte liaison encodeur M1 *)
ELSE
    DeviceEncoderM1.ErrorId := DeviceEncoderM1.ErrorId AND 16#FFDF; (* Effacement auto dès que RUNNING *)
END_IF;

// 🔍 6. DIAGNOSTIC ENCODEUR M2 (COD2_CODEUR / WinchM2)
DeviceEncoderM2.Online := EncoderM2OnlineEff;
DeviceEncoderM2.Operational := EncoderM2OnlineEff;

IF NOT DeviceEncoderM2.Online THEN
    DeviceEncoderM2.ErrorId := DeviceEncoderM2.ErrorId OR 16#0030;  (* Perte liaison encodeur M2 *)
ELSE
    DeviceEncoderM2.ErrorId := DeviceEncoderM2.ErrorId AND 16#FFCF; (* Effacement auto dès que RUNNING *)
END_IF;

{endregion}

{region "§4 Etats diagnostic par equipement"}
// 🚦 7. STATE MACHINES DE CHAQUE APPAREIL
IF DeviceVariateur.ErrorId <> 0 THEN
    DeviceVariateur.State := E_Diag_State.ERROR;
ELSIF NOT VariateurOnlineEff THEN
    DeviceVariateur.State := E_Diag_State.INIT;
ELSIF VariateurBypass AND NOT VariateurOnlineReal THEN
    DeviceVariateur.State := E_Diag_State.SIMULATED;
ELSE
    DeviceVariateur.State := E_Diag_State.READY;
END_IF;

IF DeviceEncoderM1.ErrorId <> 0 THEN
    DeviceEncoderM1.State := E_Diag_State.ERROR;
ELSIF NOT EncoderM1OnlineEff THEN
    DeviceEncoderM1.State := E_Diag_State.INIT;
ELSIF EncoderM1Bypass AND NOT EncoderM1OnlineReal THEN
    DeviceEncoderM1.State := E_Diag_State.SIMULATED;
ELSE
    DeviceEncoderM1.State := E_Diag_State.READY;
END_IF;

IF DeviceEncoderM2.ErrorId <> 0 THEN
    DeviceEncoderM2.State := E_Diag_State.ERROR;
ELSIF NOT EncoderM2OnlineEff THEN
    DeviceEncoderM2.State := E_Diag_State.INIT;
ELSIF EncoderM2Bypass AND NOT EncoderM2OnlineReal THEN
    DeviceEncoderM2.State := E_Diag_State.SIMULATED;
ELSE
    DeviceEncoderM2.State := E_Diag_State.READY;
END_IF;

{endregion}

{region "§5 Synthese EtherCAT et sorties"}
// 📤 8. RÉSUMÉ ET DÉFAUTS
DeviceVariateur.Error := (DeviceVariateur.ErrorId <> 0);
DeviceEncoderM1.Error := (DeviceEncoderM1.ErrorId <> 0);
DeviceEncoderM2.Error := (DeviceEncoderM2.ErrorId <> 0);

DeviceEthercatMaster.Online := (VariateurOnlineEff AND EncoderM1OnlineEff AND EncoderM2OnlineEff) OR NetworkBypassActive OR EcatBusBypassActive;
DeviceEthercatMaster.Operational := DeviceEthercatMaster.Online;
DeviceEthercatMaster.Error := NOT DeviceEthercatMaster.Operational;

IF DeviceEthercatMaster.Error THEN
    DeviceEthercatMaster.ErrorId := 16#0001;
    DeviceEthercatMaster.State := E_Diag_State.ERROR;
ELSIF (VariateurBypass OR EncoderM1Bypass OR EncoderM2Bypass OR EcatBusBypassActive) THEN
    DeviceEthercatMaster.ErrorId := 16#0000;
    DeviceEthercatMaster.State := E_Diag_State.SIMULATED;
ELSE
    DeviceEthercatMaster.ErrorId := 16#0000;
    DeviceEthercatMaster.State := E_Diag_State.READY;
END_IF;
{endregion}

{region "§1 Gate neutralisation"}
IF NOT Enable THEN
    Ready := FALSE;
    Measurement.RawPos := 0; Measurement.EncoderAvailable := FALSE;
    Measurement.CablePosM := 0.0; Measurement.CablePosMSafe := 0.0; Measurement.EncoderIncoherent := FALSE;
    Measurement.Speed_Mps := 0.0; Measurement.SignedSpeed_Mps := 0.0; Measurement.SpeedValid := FALSE;
    Measurement.HomingFault.Error := FALSE; Measurement.HomingFault.ErrorId := 0;
    Measurement.HomingLifecycle.Busy := FALSE; Measurement.HomingLifecycle.Done := FALSE;
    Measurement.AbsFault.Error := FALSE;    Measurement.AbsFault.ErrorId := 0;
    EncoderFault := TRUE;
    HomedAndReliable := FALSE;
    // Frontiere HW sortie : aucun ordre preset publie hors autorisation
    // (sinon PRG_02_Acquisition relaie une valeur perimee au codeur absolu -> preset parasite, reference corrompue)
    HwOut.PresetTriggerCmd := 0; HwOut.CodeSeqTriggerCmd := 0; HwOut.PresetValueOut := 0;
    // Reference connue MAINTENUE depuis Calib (RETAIN) meme FB desactive (AF09 §4) :
    // un FB desactive ne doit pas faire perdre la reference aux consommateurs aval (PRG_04, FB_Encoder_Scale).
    Homed := Calib.Homed;
    HomingSuspect := Calib.HomingSuspect;
    Measurement.HomingRefRaw := Calib.HomingRefRaw;
    // PresetConfirmationFailed est un diagnostic latch : il reste gele hors Enable
    // et ne doit pas etre efface par ce gate (AC3).
    // Socle appele meme Enable=FALSE : maintient le latch non acquitte et traite le Reset
    // hors autorisation (AC4). Les causes ne sont pas evaluees (Enable=FALSE -> vue live a 0),
    // les latches sont preserves.
    instFault(Enable := FALSE, Reset := Reset, Causes := instCauses);
    Fault := instFault.Fault;
    RETURN;
END_IF;
Ready := TRUE;
{endregion}

{region "§2 Abs"}
    instAbs(
    Enable              := Enable,
    Reset               := Reset,
    RawPosIn            := HwIn.RawPosIn,
    AlarmsIn            := HwIn.AlarmsIn,
    WarningsIn          := HwIn.WarningsIn,
    SlaveOperational    := HwIn.SlaveOperational,
    PresetRequest       := instHoming.PresetRequest,
    PresetValue         := instHoming.PresetValue,
    PointsPerRev        := PointsPerRev
);
{endregion}

{region "§3 Homing"}
instHoming(
    Enable               := Enable,
    Reset                := Reset,
    Home                 := HomingAtTargetM,
    HomingPermit         := HomingPermit,
    BtnConfirmCoherence  := ConfirmCoherence,
    UseDynamicTarget     := UseDynamicTarget,
    DynamicHomingTargetM := DynamicHomingTargetM,
    CfgHomingTargetM     := CfgHomingTargetM,
    CfgTopSensorPosM     := SEL(HomingAtZero, CfgTopSensorPosM, 0.0),
    TopPositionSensor    := TopPositionSensor,
    RawPos               := instAbs.RawPos,
    EncoderAvailable     := instAbs.EncoderAvailable,
    PresetStatusBit      := HwIn.PresetStatusBit,
    Cfg                  := Cfg,
    PointsPerRev         := PointsPerRev,
    MultiTurnRevsMax     := 4096,
    CableM_PerRev        := CableM_PerRev,
    BypassGlobal         := BypassGlobal,
    Calib                := Calib
);
{endregion}

{region "§4 Scale"}
instScale(
    RawPos       := instAbs.RawPos,
    HomingRefRaw := instHoming.HomingRefRaw,
    CableM_PerRev := CableM_PerRev,
    PointsPerRev := PointsPerRev
);
{endregion}

{region "§5 Safety"}
instSafety(
    Enable             := Enable,
    Reset              := Reset,
    CablePosM          := instScale.CablePosM,
    HomingSuspect      := instHoming.HomingSuspect,
    PositionMinM       := PositionMinM,
    PositionMaxM       := PositionMaxM,
    BypassGlobal       := BypassGlobal
);
{endregion}

{region "§6 Reliability"}
instRel(
    EncoderAvailable  := instAbs.EncoderAvailable,
    Homed             := instHoming.Homed,
    EncoderIncoherent := instSafety.EncoderIncoherent
);
{endregion}

{region "§7 Speed"}
instSpeed(
    Enable        := Enable,
    Reset         := Reset,
    Position_M    := instSafety.CablePosMSafe,
    PositionValid := NOT instRel.EncoderFault
);
{endregion}

{region "§8 Remplissage struct et synthese"}
Measurement.RawPos            := instAbs.RawPos;
Measurement.EncoderAvailable  := instAbs.EncoderAvailable;
Measurement.CablePosM         := instSafety.CablePosMSafe;
Measurement.CablePosMSafe     := instSafety.CablePosMSafe;
Measurement.EncoderIncoherent := instSafety.EncoderIncoherent;
Measurement.Speed_Mps         := instSpeed.Speed_Mps;
Measurement.SignedSpeed_Mps   := instSpeed.SignedSpeed_Mps;
Measurement.SpeedValid        := instSpeed.Valid;
Measurement.HomingFault        := instHoming.Fault;
Measurement.HomingLifecycle    := instHoming.Lifecycle;
Measurement.AbsFault           := instAbs.Fault;
Measurement.HomingRefRaw      := instHoming.HomingRefRaw;

// Frontiere HW sortie (preset)
HwOut.PresetTriggerCmd := instAbs.PresetTriggerCmd;
HwOut.CodeSeqTriggerCmd := instAbs.CodeSeqTriggerCmd;
HwOut.PresetValueOut    := instAbs.PresetValueOut;

// Etats codeur
Homed            := instHoming.Homed;
HomingSuspect    := instHoming.HomingSuspect;
EncoderFault     := instRel.EncoderFault;
HomedAndReliable := instRel.HomedAndReliable;
PresetConfirmationFailed := instHoming.PresetConfirmationFailed;

// Synthese statut facade : brique defaut socle (Fault:ST_Fault), pattern FB_Joystick.
// Causes exprimees en CLAIR (ST_FaultCause), alimentees UNIQUEMENT depuis les sorties
// publiques des sous-FB (encapsulation stricte, jamais de lecture VAR interne).
//   - Cause 0/1 : LIVE (Latching=FALSE) -> Fault.Error, retombe seule.
//   - Cause 2   : LATCHED (Latching=TRUE) -> arme Fault.Latched, acquittee au Reset front.
// Interlock machine toujours sur les faits bruts (EncoderFault, HomedAndReliable,
// EncoderIncoherent), jamais sur Fault.Latched (conservation).
instCauses[0].Active := NOT instAbs.EncoderAvailable; instCauses[0].Latching := FALSE;
instCauses[0].Texte := 'Perte materiel / communication codeur EtherCAT';
instCauses[1].Active := instSafety.EncoderIncoherent; instCauses[1].Latching := FALSE;
instCauses[1].Texte := 'Incoherence mesure / saut de position codeur';
instCauses[2].Active := instHoming.PresetConfirmationFailed; instCauses[2].Latching := TRUE;
instCauses[2].Texte := 'Echec confirmation transaction preset codeur';

// Socle appele APRES le pipeline : causes du scan courant, aucun scan de retard (AC4).
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;     // source de verite = socle
Ready := Enable AND NOT Fault.Latched;
{endregion}

{region "§1 CAUSES + SOCLE (appele AVANT le gate)"}
// 🎯 CAUSES exprimées en CLAIR (liste ST_FaultCause) — plus de bitfield WORD.
//    - CalibFail : cause A ACQUITTER (Latching=TRUE) -> arme Fault.Latched.
//    - RawOutOfRange / BusLost : cause LIVE seulement (Latching=FALSE) -> Fault.Error, retombe seule.
//    Interlock sur la cause brute ; le socle gère latch/reset.
RawOutOfRange := (RawX < (0 - Cfg.RawOutOfRangeMargin))
              OR (RawX > (10000 + Cfg.RawOutOfRangeMargin))
              OR (RawY < (0 - Cfg.RawOutOfRangeMargin))
              OR (RawY > (10000 + Cfg.RawOutOfRangeMargin));
BusLost := (NOT BusCanOpenOP.Operational OR NOT JoystickOP.Operational);

// Calibration : un front (Calibrate) hors zone -> cause a acquitter. La cause reste active tant que
// les axes sont HORS zone valide [2000..8000] : Reset ne l'efface que si la cause a disparu
// (interlock socle sur la cause brute). Effacee par un Reset avec axes en zone.
IF Calibrate AND NOT LastCalibrate THEN
    IF RawX >= 2000 AND RawX <= 8000 AND RawY >= 2000 AND RawY <= 8000 THEN
        NeutralXMem := RawX;       // memorisation nouvelle position neutre X
        NeutralYMem := RawY;       // memorisation nouvelle position neutre Y
        CalibFail := FALSE;        // calibration valide : plus de cause
    ELSE
        CalibFail := TRUE;         // échec : cause a acquitter (persistante tant que hors zone)
    END_IF;
END_IF;
LastCalibrate := Calibrate;
// Ré-acquisition de la cause (front Reset + cause disparue) : n'efface la cause QUE si les
// axes sont revenus en zone valide. Reste latee tant que hors zone (interlock sur cause brute).
IF Reset AND (RawX >= 2000 AND RawX <= 8000 AND RawY >= 2000 AND RawY <= 8000) THEN
    CalibFail := FALSE;
END_IF;

// Remplissage de la LISTE de causes pour le socle (index 0..2)
// Cause en clair (Active/Latching/Texte) ; 3 causes fixes.
instCauses[0].Active := CalibFail;     instCauses[0].Latching := TRUE;
instCauses[0].Texte := 'Echec calibration joystick (RawX/Y hors zone)';
instCauses[1].Active := RawOutOfRange; instCauses[1].Latching := FALSE;
instCauses[1].Texte := 'Capteur joystick hors plage ADC';
instCauses[2].Active := BusLost;       instCauses[2].Latching := FALSE;
instCauses[2].Texte := 'Perte liaison bus CAN joystick';

// Appel du socle TOUJOURS (meme si le gate RETURN ensuite) : la cause bus doit etre vue.
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;     // source de verite = socle

// Disponibilite = Enable + bus OK + pas de defaut LATE. Une cause live (bus, capteur) ne latche pas
// -> elle n'entre pas dans Fault.Latched ; le bus est deja couvert par ...OP.Operational ci-dessous.
Ready := Enable AND BusCanOpenOP.Operational AND JoystickOP.Operational AND NOT Fault.Latched;
{endregion}

{region "§2 Gate securite (neutralisation pipeline, n efface pas le statut)"}
// 1. GATE — neutralise le pipeline si indisponible. Le statut a deja ete rempli (zone 0).
IF NOT Enable OR BusLost THEN
    AxisCmdX.Enable := FALSE; AxisCmdX.StartStop := FALSE; AxisCmdX.SpeedTgt := 0.0; AxisCmdX.StepTgt := 0;
    AxisCmdX.DirectionPositive := FALSE; AxisCmdX.DirectionNegative := FALSE; AxisCmdX.AtNeutral := TRUE;
    AxisCmdY.Enable := FALSE; AxisCmdY.StartStop := FALSE; AxisCmdY.SpeedTgt := 0.0; AxisCmdY.StepTgt := 0;
    AxisCmdY.DirectionPositive := FALSE; AxisCmdY.DirectionNegative := FALSE; AxisCmdY.AtNeutral := TRUE;
    AxisCmdX.Direction := 0; AxisCmdX.Deflection := 0;
    AxisCmdY.Direction := 0; AxisCmdY.Deflection := 0;
    AtNeutralXY := TRUE;
    DeadmanArmed := FALSE;
    DeadmanArmPending := FALSE;
    InversionLockActive := FALSE;
    PrevDirX := 0;
    PrevDirY := 0;
    ArmingPermitDenied := FALSE;
    NeutralXYEdge(CLK := FALSE);
    NeutralHoldTimer(IN := FALSE, PT := Cfg.NeutralHoldTime);
    DeadmanArmTimer(IN := FALSE, PT := Cfg.DeadmanArmHoldTime);
    DeadmanArmGraceTimer(IN := FALSE, PT := Cfg.DeadmanArmGraceTime);
    NeutralXAct := NeutralXMem;
    NeutralYAct := NeutralYMem;
    RETURN;
END_IF;
{endregion}

{region "§3 Acquisition + mise a l echelle"}
// Mise a l'echelle (deadband) - le neutre s'evalue sur les 2 axes
ScaleX(RawIn := RawX, Neutral := NeutralXMem, DeadbandRaw := Cfg.DeadbandRaw);
ScaleY(RawIn := RawY, Neutral := NeutralYMem, DeadbandRaw := Cfg.DeadbandRaw);
AtNeutralXY := (ScaleX.OutPct = 0.0) AND (ScaleY.OutPct = 0.0);   // les 2 axes en zone morte - permis mouvement
{endregion}

{region "§4 Armement homme mort"}
// 🔀 Inversion inter-scan : le sens n'est RETENU que si la déflexion dépasse
// CST_InversionFlipThreshold_Pct (>> bruit Hall / bord de deadband). Un aller-retour
// +1<->-1 sans échantillon 0 pose le verrou. Levé exclusivement au front AtNeutralXY.
// RawOutOfRange : lecture capteur non fiable -> aucun sens retenu (le geste est déjà forcé à 0
// par le SEL du pipeline). Une reprise capteur-défaut -> valide ne compte donc pas comme flip.
DirX := 0;
DirY := 0;
IF NOT RawOutOfRange THEN
    IF ScaleX.OutPct > CST_InversionFlipThreshold_Pct THEN
        DirX := 1;
    ELSIF ScaleX.OutPct < -CST_InversionFlipThreshold_Pct THEN
        DirX := -1;
    END_IF;
    IF ScaleY.OutPct > CST_InversionFlipThreshold_Pct THEN
        DirY := 1;
    ELSIF ScaleY.OutPct < -CST_InversionFlipThreshold_Pct THEN
        DirY := -1;
    END_IF;
END_IF;
FlipX := ((PrevDirX = 1) AND (DirX = -1)) OR ((PrevDirX = -1) AND (DirX = 1));
FlipY := ((PrevDirY = 1) AND (DirY = -1)) OR ((PrevDirY = -1) AND (DirY = 1));

NeutralXYEdge(CLK := AtNeutralXY);
IF NeutralXYEdge.Q THEN
    InversionLockActive := FALSE;
END_IF;

IF FlipX OR FlipY THEN
    InversionLockActive := TRUE;
    DeadmanArmed := FALSE;
    DeadmanArmPending := FALSE;
END_IF;

// Bouton homme-mort : armement par MAINTIEN (Cfg.DeadmanArmHoldTime), independant de la position.
// ⚠️ Un appui PENDANT le verrou d'inversion n'arme PAS de demande : le nouveau front conscient
//    doit survenir APRÈS le retour au neutre (sinon on "pré-charge" le réarmement stick inversé).
DeadmanEdge(CLK := RawButton);
IF DeadmanEdge.Q AND NOT InversionLockActive THEN DeadmanArmPending := TRUE; END_IF;
IF NOT RawButton THEN DeadmanArmPending := FALSE; END_IF;

// Securite : armage UNIQUEMENT si DeadmanArmPending ET ArmingPermit.
DeadmanArmTimer(IN := DeadmanArmPending AND NOT DeadmanArmed AND ArmingPermit AND NOT InversionLockActive, PT := Cfg.DeadmanArmHoldTime);
IF DeadmanArmTimer.Q THEN
    DeadmanArmed := TRUE;
    DeadmanArmPending := FALSE;
END_IF;

// Désarmement externe immédiat : le retrait d'ArmingPermit (changement de mode, fin de cycle
// benne) désarme TOUT DE SUITE le geste — pas d'armement résiduel "surprise" à la ré-acquisition.
IF NOT ArmingPermit THEN
    DeadmanArmed := FALSE;
    DeadmanArmPending := FALSE;
END_IF;

// Avertissement "armage non autorise" (niveau, pendant l'appui non autorise)
ArmingPermitDenied := RawButton AND NOT ArmingPermit;

// Desarmage par maintien au neutre (apres grace)
DeadmanArmGraceTimer(IN := DeadmanArmed, PT := Cfg.DeadmanArmGraceTime);
NeutralHoldTimer(IN := DeadmanArmed AND AtNeutralXY AND DeadmanArmGraceTimer.Q, PT := Cfg.NeutralHoldTime);
IF NeutralHoldTimer.Q THEN DeadmanArmed := FALSE; END_IF;
{endregion}

{region "§5 Pipeline axe X"}
CmdXVal := SEL(DeadmanArmed AND NOT RawOutOfRange, 0.0, ScaleX.OutPct);

AxisCmdX.Enable := NOT RawOutOfRange AND ArmingPermit;
AxisCmdX.SpeedTgt := ABS(CmdXVal);   // NON signee (le sens = bits DirectionPositive/Negative + AxisCmdX.Direction)
AxisCmdX.StartStop := (ABS(CmdXVal) > CST_DirectionQualificationThreshold_Pct);

AxisCmdX.DirectionPositive := (CmdXVal > CST_DirectionQualificationThreshold_Pct);
AxisCmdX.DirectionNegative := (CmdXVal < -CST_DirectionQualificationThreshold_Pct);
AxisCmdX.AtNeutral := NOT AxisCmdX.DirectionPositive AND NOT AxisCmdX.DirectionNegative;
IF AxisCmdX.AtNeutral THEN AxisCmdX.SpeedTgt := 0.0; END_IF;

// Projections monitoring dans le struct (les bits restent la source logique)
IF AxisCmdX.DirectionPositive THEN AxisCmdX.Direction := 1;
ELSIF AxisCmdX.DirectionNegative THEN AxisCmdX.Direction := -1;
ELSE AxisCmdX.Direction := 0; END_IF;
AxisCmdX.Deflection := REAL_TO_INT(CmdXVal);   // deflexion signee -100..+100 % (anim IHM)
{endregion}

{region "§6 Pipeline axe Y et sorties"}
CmdYVal := SEL(DeadmanArmed AND NOT RawOutOfRange, 0.0, ScaleY.OutPct);

AxisCmdY.Enable := NOT RawOutOfRange AND ArmingPermit;
AxisCmdY.SpeedTgt := ABS(CmdYVal);   // NON signee (le sens = bits DirectionPositive/Negative + AxisCmdY.Direction)
AxisCmdY.StartStop := (ABS(CmdYVal) > CST_DirectionQualificationThreshold_Pct);

AxisCmdY.DirectionPositive := (CmdYVal > CST_DirectionQualificationThreshold_Pct);
AxisCmdY.DirectionNegative := (CmdYVal < -CST_DirectionQualificationThreshold_Pct);
AxisCmdY.AtNeutral := NOT AxisCmdY.DirectionPositive AND NOT AxisCmdY.DirectionNegative;
IF AxisCmdY.AtNeutral THEN AxisCmdY.SpeedTgt := 0.0; END_IF;

// 🪜 Decodage consigne % -> palier (logique FB_Winch §5, deplacee au joystick).
//    AxisCmdY.SpeedTgt (%) reste pour l'IHM ; AxisCmdY.StepTgt (1..5, 0=arret) pour la logique/limitations.
SpeedStepHyst1(IN := REAL_TO_INT(AxisCmdY.SpeedTgt), HIGH := REAL_TO_INT(Cfg.SpeedStepTable.StepThreshold_Pct[1] + Cfg.SpeedStepHystMargin), LOW := REAL_TO_INT(Cfg.SpeedStepTable.StepThreshold_Pct[1] - Cfg.SpeedStepHystMargin));
SpeedStepHyst2(IN := REAL_TO_INT(AxisCmdY.SpeedTgt), HIGH := REAL_TO_INT(Cfg.SpeedStepTable.StepThreshold_Pct[2] + Cfg.SpeedStepHystMargin), LOW := REAL_TO_INT(Cfg.SpeedStepTable.StepThreshold_Pct[2] - Cfg.SpeedStepHystMargin));
SpeedStepHyst3(IN := REAL_TO_INT(AxisCmdY.SpeedTgt), HIGH := REAL_TO_INT(Cfg.SpeedStepTable.StepThreshold_Pct[3] + Cfg.SpeedStepHystMargin), LOW := REAL_TO_INT(Cfg.SpeedStepTable.StepThreshold_Pct[3] - Cfg.SpeedStepHystMargin));
SpeedStepHyst4(IN := REAL_TO_INT(AxisCmdY.SpeedTgt), HIGH := REAL_TO_INT(Cfg.SpeedStepTable.StepThreshold_Pct[4] + Cfg.SpeedStepHystMargin), LOW := REAL_TO_INT(Cfg.SpeedStepTable.StepThreshold_Pct[4] - Cfg.SpeedStepHystMargin));

// ⚠️ HYSTERESIS (Util CODESYS) est un hystérésis BAS : OUT=TRUE quand IN<LOW, OUT=FALSE
//    quand IN>HIGH. Pour un décodage ASCENDANT (petite déflexion → palier bas, grande →
//    palier haut) on teste donc `NOT OUT` : palier supérieur seulement une fois IN au-dessus
//    du seuil (bande d'hystérésis LOW..HIGH autour de StepThreshold_Pct[n]).
IF AxisCmdY.SpeedTgt <= CST_DirectionQualificationThreshold_Pct THEN
    AxisCmdY.StepTgt := 0;
ELSE
    AxisCmdY.StepTgt := 1;
    IF NOT SpeedStepHyst1.OUT THEN AxisCmdY.StepTgt := 2; END_IF;
    IF NOT SpeedStepHyst2.OUT THEN AxisCmdY.StepTgt := 3; END_IF;
    IF NOT SpeedStepHyst3.OUT THEN AxisCmdY.StepTgt := 4; END_IF;
    IF NOT SpeedStepHyst4.OUT THEN AxisCmdY.StepTgt := 5; END_IF;
END_IF;

// Projections monitoring dans le struct (les bits restent la source logique)
IF AxisCmdY.DirectionPositive THEN AxisCmdY.Direction := 1;
ELSIF AxisCmdY.DirectionNegative THEN AxisCmdY.Direction := -1;
ELSE AxisCmdY.Direction := 0; END_IF;
AxisCmdY.Deflection := REAL_TO_INT(CmdYVal);   // deflexion signee -100..+100 % (anim IHM)

// Memorisation apres traitement : l'inversion suivante compare deux scans qualifies successifs.
PrevDirX := DirX;
PrevDirY := DirY;

// Miroirs point neutre courant
NeutralXAct := NeutralXMem;
NeutralYAct := NeutralYMem;
{endregion}

{region "§1 Fronts, remises a zero de tete de scan, verrou M3"}
// === §1 FRONTS + RAZ TETE DE SCAN + VERROU M3 =========================

// Sorties impulsionnelles / mouvement : remises a FALSE en tete de scan.
// Seul un step actif les remonte -> HX0 (etape initiale pure) n'ecrit rien.
M1Demand.HomeReq := FALSE;
M2Demand.HomeReq := FALSE;
BucketCommit.CommitOpen  := FALSE;
BucketCommit.CommitClose := FALSE;
CmdBucketOpen  := FALSE;
CmdBucketClose := FALSE;
CmdWinchM1.RunRequest := FALSE; CmdWinchM1.ReqAscent := FALSE; CmdWinchM1.ReqDescend := FALSE; CmdWinchM1.StepTgt := 0;
CmdWinchM2.RunRequest := FALSE; CmdWinchM2.ReqAscent := FALSE; CmdWinchM2.ReqDescend := FALSE; CmdWinchM2.StepTgt := 0;
ExplicitValidationPulse := FALSE;

// Detection de fronts.
ResetEdge(CLK := Reset);
LatchedEdge(CLK := Fault.Latched);
TopLostEdge(CLK := TopPositionSensor);

// Miroirs booleens de contexte GRAFCET.
IsInMovePhase := (SeqStep = E_MachineHomingTxState.HX2_CLIMB)
              OR (SeqStep = E_MachineHomingTxState.HX3_HOME_AXES);
CycleRunning := (SeqStep <> E_MachineHomingTxState.HX0_REPOS)
             AND (SeqStep <> E_MachineHomingTxState.HX1_CHOICE);

// M3Locked est calcule en §9 (apres le CASE) pour verrouiller des le scan d'entree en cycle.
{endregion}

{region "§2 Conditions intermediaires & motif de validation 3 appuis"}
// === §2 CONDITIONS NOMMEES + VALIDATION EXPLICITE =====================
BothAxesHomed       := M1Status.HomedAndReliable AND M2Status.HomedAndReliable;
CommitOrOffsetValid := CommitPublished OR BucketOffsetValid;
ClimbPermit         := DeadmanArmed AND JoystickPull;
DescendPermit       := DeadmanArmed AND JoystickPush;
BucketPermit        := DeadmanArmed AND JoystickDeflected;

// Fenetre de grace deceleration : armee des qu'on entre un step d'arret depuis une phase mouvement.
SettleGraceTimer(IN := (SeqStep = E_MachineHomingTxState.HX2N_NEUTRAL)
                       OR (SeqStep = E_MachineHomingTxState.HX3N_PAUSE), PT := CST_SettleGrace);

// Conditions d'abandon fail-safe, chacune <= 3 termes (std 2quater).
AxisHomingError  := M1Status.HomingError OR M2Status.HomingError;
MotionOutOfPhase := CycleRunning AND NOT IsInMovePhase
                    AND NOT WinchesMechanicallyStopped AND SettleGraceTimer.Q;
ClimbTimedOut    := (SeqStep = E_MachineHomingTxState.HX2_CLIMB) AND ClimbTimer.Q;
HomeAxesTimedOut := (SeqStep = E_MachineHomingTxState.HX3_HOME_AXES) AND HomeAxesTimer.Q AND NOT BothAxesHomed;
TransactionAbort := CycleRunning
                    AND (AxisHomingError OR MotionOutOfPhase OR ClimbTimedOut OR HomeAxesTimedOut);

// --- Motif "3 appuis successifs" -> ExplicitValidationPulse ---
// Pre-conditions permanentes : joystick centre + aucun mouvement + homme-mort arme.
ValidationBtnEdgeR(CLK := BtnValidation);
ValidationBtnEdgeF(CLK := BtnValidation);
ValidationHoldTimer(IN := BtnValidation, PT := CST_ValidationHold);
ValidationGapTimer(IN := (ValidationPressCount > 0) AND NOT BtnValidation, PT := CST_ValidationGap);

// Latch "appui maintenu assez longtemps" : lu au relachement (le TON retombe le meme
// scan que la chute de BtnValidation, donc on ne peut pas tester holdTimer.Q sur le front F).
IF BtnValidation AND ValidationHoldTimer.Q THEN
    ValidationHeldOk := TRUE;
END_IF;

IF JoystickDeflected OR NOT WinchesMechanicallyStopped OR NOT DeadmanArmed THEN
    ValidationPressCount := 0;
    ValidationHeldOk     := FALSE;
ELSIF ValidationGapTimer.Q THEN
    ValidationPressCount := 0;                       // fenetre entre appuis depassee
    ValidationHeldOk     := FALSE;
ELSIF ValidationBtnEdgeF.Q AND ValidationHeldOk THEN
    ValidationPressCount := ValidationPressCount + 1; // appui maintenu >= 300 ms puis relache -> compte
    ValidationHeldOk     := FALSE;
END_IF;

IF ValidationPressCount >= CST_ValidationCount THEN
    ExplicitValidationPulse := TRUE;                 // impulsion 1 scan
    ValidationPressCount    := 0;
END_IF;
{endregion}

{region "§3 Detection de perte de datum (independante de Fault)"}
// === §3 DETECTION DE PERTE DE DATUM ==================================
MachineHomedRaw := BothAxesHomed AND CommitOrOffsetValid
                   AND NOT MachineHomingFailed AND NOT ReHomingAckRequired;

IF MachineHomedRaw THEN
    MachineWasHomed := TRUE;
END_IF;
IF MachineWasHomed AND NOT MachineHomedRaw AND NOT WinchesMechanicallyStopped THEN
    HomingLossLatched := TRUE;
END_IF;
IF NOT MachineHomedRaw AND WinchesMechanicallyStopped THEN
    MachineWasHomed := FALSE;
END_IF;
IF HomingLossLatched AND WinchesMechanicallyStopped THEN
    HomingLossLatched := FALSE;
END_IF;

(* C : pas de redemarrage automatique. Une perte de datum en mouvement exige un
   acquittement conscient (front Reset) avant que MachineHomed puisse revenir. *)
IF HomingLossLatched AND NOT ReHomingAckRequired THEN
    ReHomingAckRequired := TRUE;
END_IF;

MachineHomingLossSafeStop := HomingLossLatched;
{endregion}

{region "§4 Purge sur front Reset (abandon cycle / acquittement)"}
// === §4 PURGE SUR FRONT RESET =======================================
IF ResetEdge.Q THEN
    SeqStep             := E_MachineHomingTxState.HX0_REPOS;
    PendingClose        := FALSE;
    CommitPublished     := FALSE;
    CommitDone          := FALSE;
    HomeReqDone         := FALSE;
    SeenNeutral         := FALSE;
    ValidationPressCount := 0;
    ValidationHeldOk    := FALSE;
    MachineHomingFailed := FALSE;
    MachineWasHomed     := FALSE;
    HomingLossLatched   := FALSE;
    ReHomingAckRequired := FALSE;
END_IF;
{endregion}

{region "§5 Table des causes & socle defaut"}
// === §5 TABLE DES CAUSES + SOCLE DEFAUT ==============================
instCauses[CST_CauseHomingLostInMotion].Active   := HomingLossLatched OR ReHomingAckRequired;
instCauses[CST_CauseHomingLostInMotion].Latching := TRUE;
instCauses[CST_CauseHomingLostInMotion].Texte    := 'Perte de datum machine en mouvement : re-referencer';

instCauses[CST_CauseClimbTimeout].Active   := ClimbTimedOut;
instCauses[CST_CauseClimbTimeout].Latching := TRUE;
instCauses[CST_CauseClimbTimeout].Texte    := 'Montee au capteur haut non aboutie dans le temps imparti';

instCauses[CST_CauseMotionOutOfPhase].Active   := MotionOutOfPhase;
instCauses[CST_CauseMotionOutOfPhase].Latching := TRUE;
instCauses[CST_CauseMotionOutOfPhase].Texte    := 'Mouvement treuil detecte hors phase autorisee du cycle';

instCauses[CST_CauseHomingErrorM1].Active   := CycleRunning AND M1Status.HomingError;
instCauses[CST_CauseHomingErrorM1].Latching := TRUE;
instCauses[CST_CauseHomingErrorM1].Texte    := 'Erreur de homing codeur M1 pendant le referencement conjoint';

instCauses[CST_CauseHomingErrorM2].Active   := CycleRunning AND M2Status.HomingError;
instCauses[CST_CauseHomingErrorM2].Latching := TRUE;
instCauses[CST_CauseHomingErrorM2].Texte    := 'Erreur de homing codeur M2 pendant le referencement conjoint';

instCauses[CST_CauseHomeAxesTimeout].Active   := HomeAxesTimedOut;
instCauses[CST_CauseHomeAxesTimeout].Latching := TRUE;
instCauses[CST_CauseHomeAxesTimeout].Texte    := 'Homing des axes non obtenu dans le temps imparti';

// Socle defaut : appele AVANT la gate NOT Enable (Reset jamais conditionne, std 9).
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;
{endregion}

{region "§6 Gate initialisation (NOT Enable)"}
// === §6 GATE NOT ENABLE : SORTIES SURES + RETURN =====================
IF NOT Enable THEN
    SeqStep                  := E_MachineHomingTxState.HX0_REPOS;
    MachineHomingStep        := E_MachineHomingStep.IDLE;
    MachineHomingSeqStep     := E_MachineHomingTxState.HX0_REPOS;
    MachineHomingInstruction := 'Referencement indisponible';
    MachineHomed             := FALSE;
    MachineHomingActive      := FALSE;
    M1Demand.HomeReq          := FALSE; M1Demand.UseDynamicTarget := FALSE;
    M2Demand.HomeReq          := FALSE; M2Demand.UseDynamicTarget := FALSE;
    CmdWinchM1.RunRequest := FALSE; CmdWinchM1.ReqAscent := FALSE; CmdWinchM1.ReqDescend := FALSE; CmdWinchM1.StepTgt := 0;
    CmdWinchM2.RunRequest := FALSE; CmdWinchM2.ReqAscent := FALSE; CmdWinchM2.ReqDescend := FALSE; CmdWinchM2.StepTgt := 0;
    CmdBucketOpen  := FALSE;
    CmdBucketClose := FALSE;
    BucketCommit.CommitOpen  := FALSE;
    BucketCommit.CommitClose := FALSE;
    Lifecycle.Busy           := FALSE;
    Lifecycle.Done           := FALSE;
    Ready                    := FALSE;
    M3Locked                 := FALSE;
    CycleRunning             := FALSE;
    HomeReqDone              := FALSE;
    SeenNeutral              := FALSE;
    RETURN;
END_IF;
{endregion}

{region "§7 Cible dynamique M2 & temporisations de garde"}
// === §7 CIBLE DYNAMIQUE M2 + GARDES ==================================
M1Demand.UseDynamicTarget := FALSE;
IF (SeqStep = E_MachineHomingTxState.HX3_HOME_AXES) THEN
    M2Demand.UseDynamicTarget := TRUE;
    M2Demand.DynamicTarget_M  := Cfg.CfgTopHomingTarget_M + Cfg.CfgOffsetClose_M;
ELSE
    M2Demand.UseDynamicTarget := FALSE;
END_IF;

ClimbTimer(IN := (SeqStep = E_MachineHomingTxState.HX2_CLIMB) AND (Cfg.CfgTimeoutClimb > T#0s),
           PT := Cfg.CfgTimeoutClimb);
HomeAxesTimer(IN := (SeqStep = E_MachineHomingTxState.HX3_HOME_AXES) AND (Cfg.CfgTimeoutHomeAxes > T#0s),
              PT := Cfg.CfgTimeoutHomeAxes);
{endregion}

{region "§8 GRAFCET de referencement machine (CASE SeqStep)"}
// === §8 GRAFCET (CASE SeqStep) ======================================
// Carte des steps HX0..HX6 + HXF, actions et receptivites : voir
//   DOC/AF/AF_Partie-09_Fonction_Encoder_v2.4.md (F09.08 - cycle de homing machine).
// Chaque arme du CASE porte 1 ligne de rappel ; la source de verite reste l'AF.
// ====================================================================
CASE SeqStep OF

    E_MachineHomingTxState.HX0_REPOS:
        // Etape initiale pure : aucune action ici.
        IF (ExplicitValidationPulse OR (MachineWasHomed AND NOT MachineHomedRaw))
           AND (Mode = E_Mode.MAINT_N2) THEN
            CommitPublished     := FALSE;   // datum invalide tant qu'il est refait (FINDING-003)
            CommitDone          := FALSE;
            MachineHomingFailed := FALSE;
            HomeReqDone         := FALSE;
            SeqStep             := E_MachineHomingTxState.HX1_CHOICE;
        END_IF;

    E_MachineHomingTxState.HX1_CHOICE:
        // Aucun ordre mouvement (garanti par la RAZ de tete de scan).
        IF ExplicitValidationPulse THEN
            IF NOT TopPositionSensor THEN
                SeqStep := E_MachineHomingTxState.HX2_CLIMB;
            ELSE
                SeenNeutral := NOT JoystickDeflected;
                SeqStep     := E_MachineHomingTxState.HX2N_NEUTRAL;
            END_IF;
        END_IF;
        // HT1a (abandon) traite par la purge §4 sur front Reset.

    E_MachineHomingTxState.HX2_CLIMB:
        // Montee couplee M1+M2 palier 1, uniquement sous permis maintenu (manche tire).
        IF ClimbPermit THEN
            CmdWinchM1.RunRequest := TRUE; CmdWinchM1.ReqAscent := TRUE; CmdWinchM1.StepTgt := CST_StepSlow;
            CmdWinchM2.RunRequest := TRUE; CmdWinchM2.ReqAscent := TRUE; CmdWinchM2.StepTgt := CST_StepSlow;
        END_IF;
        IF TransactionAbort THEN
            MachineHomingFailed := TRUE;
            SeqStep := E_MachineHomingTxState.HXF_FAILED;
        ELSIF TopPositionSensor THEN
            SeenNeutral := NOT JoystickDeflected;
            SeqStep     := E_MachineHomingTxState.HX2N_NEUTRAL;
        END_IF;

    E_MachineHomingTxState.HX2N_NEUTRAL:
        // Mouvement nul obligatoire entre montee (tire) et descente (pousse).
        IF NOT JoystickDeflected THEN
            SeenNeutral := TRUE;
        END_IF;
        IF TransactionAbort THEN
            MachineHomingFailed := TRUE;
            SeqStep := E_MachineHomingTxState.HXF_FAILED;
        ELSIF WinchesMechanicallyStopped AND SeenNeutral AND DescendPermit
              AND TopPositionSensor THEN
            HomeReqDone := FALSE;
            SeqStep     := E_MachineHomingTxState.HX3_HOME_AXES;
        END_IF;

    E_MachineHomingTxState.HX3_HOME_AXES:
        // Descente couplee M1+M2 palier 1 sous permis maintenu (manche pousse).
        IF DescendPermit THEN
            CmdWinchM1.RunRequest := TRUE; CmdWinchM1.ReqDescend := TRUE; CmdWinchM1.StepTgt := CST_StepSlow;
            CmdWinchM2.RunRequest := TRUE; CmdWinchM2.ReqDescend := TRUE; CmdWinchM2.StepTgt := CST_StepSlow;
        END_IF;
        // Homing des AXES seulement, au vol, sur le front DESCENDANT du capteur.
        IF TopLostEdge.Q AND NOT HomeReqDone THEN
            M1Demand.HomeReq := TRUE;
            M2Demand.HomeReq := TRUE;
            HomeReqDone      := TRUE;
        END_IF;
        IF TransactionAbort THEN
            MachineHomingFailed := TRUE;
            SeqStep := E_MachineHomingTxState.HXF_FAILED;
        ELSIF NOT TopPositionSensor AND M1Status.HomedAndReliable AND M2Status.HomedAndReliable THEN
            SeenNeutral := NOT JoystickDeflected;
            SeqStep     := E_MachineHomingTxState.HX3N_PAUSE;
        END_IF;

    E_MachineHomingTxState.HX3N_PAUSE:
        // Arret avant benne : treuils + benne a 0 (RAZ tete de scan), retour au neutre.
        IF NOT JoystickDeflected THEN
            SeenNeutral := TRUE;
        END_IF;
        IF TransactionAbort THEN
            MachineHomingFailed := TRUE;
            SeqStep := E_MachineHomingTxState.HXF_FAILED;
        ELSIF WinchesMechanicallyStopped AND SeenNeutral THEN
            SeqStep := E_MachineHomingTxState.HX4_BUCKET_ADJUST;
        END_IF;

    E_MachineHomingTxState.HX4_BUCKET_ADJUST:
        // Benne palier 1 SANS FDC soft, 2 sens ; treuils a 0.
        IF BucketPermit AND JoystickPull THEN
            CmdBucketClose := TRUE;
        ELSIF BucketPermit AND JoystickPush THEN
            CmdBucketOpen := TRUE;
        END_IF;
        IF AxisHomingError THEN
            MachineHomingFailed := TRUE;
            SeqStep := E_MachineHomingTxState.HXF_FAILED;
        ELSIF ExplicitValidationPulse AND NOT JoystickDeflected AND WinchesMechanicallyStopped THEN
            PendingClose := TRUE;
            CommitDone   := FALSE;
            SeqStep      := E_MachineHomingTxState.HX5_BUCKET_COMMIT;
        END_IF;

    E_MachineHomingTxState.HX5_BUCKET_COMMIT:
        // Commit atomique de l'etat benne : impulsion 1 scan garantie via CommitDone.
        IF AxisHomingError OR NOT BothAxesHomed THEN
            MachineHomingFailed := TRUE;
            SeqStep := E_MachineHomingTxState.HXF_FAILED;
        ELSIF NOT CommitDone THEN
            BucketCommit.CommitClose := PendingClose;
            CommitPublished          := TRUE;
            CommitDone               := TRUE;
        ELSE
            PendingClose := FALSE;
            SeqStep      := E_MachineHomingTxState.HX6_HOMED;
        END_IF;

    E_MachineHomingTxState.HX6_HOMED:
        // MachineHomed calcule en §9. Retour immediat a l'etape initiale.
        SeqStep := E_MachineHomingTxState.HX0_REPOS;

    E_MachineHomingTxState.HXF_FAILED:
        // Sortie uniquement sur front Reset conscient (purge §4).
        ;

END_CASE;
{endregion}

{region "§9 Cycle de vie & qualification de sortie"}
// === §9 CYCLE DE VIE + QUALIFICATION ================================
CycleRunning := (SeqStep <> E_MachineHomingTxState.HX0_REPOS)
             AND (SeqStep <> E_MachineHomingTxState.HX1_CHOICE);
// Verrou translation : interdite des qu'on quitte l'etape initiale (calcul post-CASE : sans retard).
M3Locked             := (SeqStep <> E_MachineHomingTxState.HX0_REPOS);
MachineHomingActive  := CycleRunning;
Lifecycle.Busy       := CycleRunning;
Lifecycle.Done       := CommitPublished AND (SeqStep = E_MachineHomingTxState.HX0_REPOS);
MachineHomingSeqStep := SeqStep;

// Qualification de sortie — calcul UNIQUE, apres le deroule GRAFCET (§8).
CommitOrOffsetValid := CommitPublished OR BucketOffsetValid;
MachineHomed := BothAxesHomed AND CommitOrOffsetValid
                AND NOT MachineHomingFailed AND NOT ReHomingAckRequired
                AND NOT Fault.Latched;
{endregion}

{region "§10 Guide operateur — echelle de priorite (IF/ELSIF, pas un dispatch d'etat)"}
// === §10 GUIDE OPERATEUR (echelle de priorite) ======================
// MachineHomingStep est RECALCULE chaque scan a partir des conditions courantes :
// l'etape est le resultat, pas l'etat ou l'on dispatche. La vraie machine a etats
// est le GRAFCET (§8, CASE SeqStep). Precedent : FB_Modes.st (echelle IF/ELSIF).
IF Fault.Latched THEN
    MachineHomingStep := E_MachineHomingStep.FAILED;
    MachineHomingInstruction := 'Defaut referencement : acquitter (Reset) puis recommencer en N2';
ELSIF MachineHomingFailed OR (SeqStep = E_MachineHomingTxState.HXF_FAILED) THEN
    MachineHomingStep := E_MachineHomingStep.FAILED;
    MachineHomingInstruction := 'Referencement incomplet : rester en N2 et recommencer';
ELSIF MachineHomingLossSafeStop THEN
    MachineHomingStep := E_MachineHomingStep.LOSS_SAFESTOP;
    MachineHomingInstruction := 'Reference perdue en mouvement : arret controle en cours';
ELSIF (SeqStep = E_MachineHomingTxState.HX2_CLIMB) THEN
    MachineHomingStep := E_MachineHomingStep.NEED_TOP_POSITION;
    MachineHomingInstruction := 'Tirer joystick - montee treuils M1 M2 Palier 1 - jusqu au capteur FDC haut';
ELSIF (SeqStep = E_MachineHomingTxState.HX2N_NEUTRAL) THEN
    MachineHomingStep := E_MachineHomingStep.NEED_MECHANICAL_STOP;
    MachineHomingInstruction := 'Joystick au neutre, attendre l arret, puis pousser pour descendre';
ELSIF (SeqStep = E_MachineHomingTxState.HX3_HOME_AXES) THEN
    MachineHomingStep := E_MachineHomingStep.HOMING_IN_PROGRESS;
    MachineHomingInstruction := 'Descente Palier 1 : homing des axes M1 M2 a la sortie du capteur';
ELSIF (SeqStep = E_MachineHomingTxState.HX3N_PAUSE) THEN
    MachineHomingStep := E_MachineHomingStep.NEED_MECHANICAL_STOP;
    MachineHomingInstruction := 'Joystick au neutre : preparation ajustement benne';
ELSIF (SeqStep = E_MachineHomingTxState.HX4_BUCKET_ADJUST) THEN
    MachineHomingStep := E_MachineHomingStep.AWAIT_BUCKET_CONFIRM;
    MachineHomingInstruction := 'Ajuster la benne (Palier 1, 2 sens) puis valider benne fermee (3 appuis)';
ELSIF (SeqStep = E_MachineHomingTxState.HX5_BUCKET_COMMIT)
      OR (SeqStep = E_MachineHomingTxState.HX6_HOMED) THEN
    MachineHomingStep := E_MachineHomingStep.VALID;
    MachineHomingInstruction := 'Etat benne fermee enregistre : validation du referencement machine';
ELSIF (SeqStep = E_MachineHomingTxState.HX1_CHOICE) THEN
    IF NOT TopPositionSensor THEN
        MachineHomingStep := E_MachineHomingStep.NEED_TOP_POSITION;
        MachineHomingInstruction := 'Machine non referencee : valider pour monter au capteur haut, ou quitter';
    ELSE
        MachineHomingStep := E_MachineHomingStep.AWAIT_BUCKET_CONFIRM;
        MachineHomingInstruction := 'Sur capteur haut : valider pour referencer, ou quitter vers MAINT_N2';
    END_IF;
ELSIF NOT M1Status.HomedAndReliable AND NOT M2Status.HomedAndReliable THEN
    MachineHomingStep := E_MachineHomingStep.BOTH_NOT_HOMED;
    MachineHomingInstruction := 'Codeurs M1 et M2 non references : lancer le cycle de homing machine (N2)';
ELSIF NOT M1Status.HomedAndReliable THEN
    MachineHomingStep := E_MachineHomingStep.M1_NOT_HOMED;
    MachineHomingInstruction := 'Codeur M1 non reference ou mesure douteuse : relancer le homing machine';
ELSIF NOT M2Status.HomedAndReliable THEN
    MachineHomingStep := E_MachineHomingStep.M2_NOT_HOMED;
    MachineHomingInstruction := 'Codeur M2 non reference ou mesure douteuse : relancer le homing machine';
ELSIF NOT (CommitPublished OR BucketOffsetValid) THEN
    IF Mode <> E_Mode.MAINT_N2 THEN
        MachineHomingStep := E_MachineHomingStep.OFFSET_UNKNOWN;
        MachineHomingInstruction := 'Offset benne inconnu : passer en maintenance N2';
    ELSE
        MachineHomingStep := E_MachineHomingStep.AWAIT_BUCKET_CONFIRM;
        MachineHomingInstruction := 'Lancer le cycle de homing machine pour enregistrer l etat benne';
    END_IF;
ELSE
    MachineHomingStep := E_MachineHomingStep.VALID;
    MachineHomingInstruction := 'Referencement machine valide : mode nominal disponible';
END_IF;

// R9 : capture de l'etape APRES recalcul du guide, au front d'apparition du defaut latche.
IF LatchedEdge.Q THEN
    MachineHomingStepAtError := MachineHomingStep;
END_IF;

Ready := Enable AND NOT Fault.Latched;
{endregion}

// === IMPLEMENTATION ===

{region "§1 Repli image reelle banc desactive"}
IF NOT Enable THEN
    // 🔌 Banc désactivé : repli sur l'image réelle, aucune simulation en cours
    Ready       := FALSE;
    Busy        := FALSE;
    Done        := FALSE;
    Winch       := HwReal.Winch;
    Translation := HwReal.Translation;
    Operator    := HwReal.Operator;
    Machine     := HwReal.Machine;
    RETURN;
END_IF;

// ▶️ Banc actif : le cycle de simulation démarre pour ce scan
Ready := TRUE;
Busy  := TRUE;
Done  := FALSE;


{endregion}

{region "§2 Simulation treuils M1/M2"}
// ── 1. MODÈLE TREUILS (M1 + M2) ─────────────────────────────────────────────
// Presets codeurs : déclenchés si PresetTriggerCmd = 2
M1_PresetCmd := (M1_PresetTriggerCmd = 2);
M2_PresetCmd := (M2_PresetTriggerCmd = 2);

// Conversions d'injection d'écart synchro (0.5m -> points codeur avec 8192 pts/tour, 2m/tour)
// 1m = 4096 points codeur.
M1_OffsetPts := REAL_TO_DINT(SimSyncDeviationOffset_M * 4096.0);
M2_OffsetPts := REAL_TO_DINT(SimSyncDeviationOffset_M * 4096.0);

// Instance modèle codeur M1
instSimEncoderM1(
    Enable           := TRUE,
    RelayFwd         := M1_RelayFwd,
    RelayRev         := M1_RelayRev,
    StepNumber       := M1_StepNumber,
    PresetCmd        := M1_PresetCmd,
    PresetValue      := M1_PresetValueOut,
    SpeedScaleFactor := SimEncoderSpeedFactor,
    TestOffsetCmd    := SimSyncDeviationInjectM1,
    TestOffsetPts    := M1_OffsetPts,
    RawPos           := RawPosM1
);

// Instance modèle codeur M2
instSimEncoderM2(
    Enable           := TRUE,
    RelayFwd         := M2_RelayFwd,
    RelayRev         := M2_RelayRev,
    StepNumber       := M2_StepNumber,
    PresetCmd        := M2_PresetCmd,
    PresetValue      := M2_PresetValueOut,
    SpeedScaleFactor := SimEncoderSpeedFactor,
    TestOffsetCmd    := SimSyncDeviationInjectM2,
    TestOffsetPts    := M2_OffsetPts,
    RawPos           := RawPosM2
);

// Recopie structures Winch simulées :
// 🛑 POLARITÉ DE FREIN SIMULÉ : 1 = contacteur commandé = frein OUVERT.
// Câblage réel : DI = 1 ⟺ frein OUVERT. Le modèle produit donc M1_BrakeIsOpen_DI := M1_BrakeCmd !
Winch.M1_BrakeIsOpen_DI        := M1_BrakeCmd;
// Retour UNIQUE « tous contacteurs retombés » = sens ET vitesse.
// Omettre les paliers ferait croire à l'arrêt pendant les transitoires → Méca A armée à tort.
Winch.M1_ContactorsReleased_DI := NOT (M1_RelayFwd OR M1_RelayRev
                                    OR M1_SpeedContactor_1 OR M1_SpeedContactor_2
                                    OR M1_SpeedContactor_3 OR M1_SpeedContactor_4);
Winch.M1_ThermalOk_DI          := TRUE; // Sauf panne simulée

Winch.M2_BrakeIsOpen_DI        := M2_BrakeCmd;
Winch.M2_ContactorsReleased_DI := NOT (M2_RelayFwd OR M2_RelayRev
                                    OR M2_SpeedContactor_1 OR M2_SpeedContactor_2
                                    OR M2_SpeedContactor_3 OR M2_SpeedContactor_4);
Winch.M2_ThermalOk_DI          := TRUE;

// Cohérent avec M2_TensionedCable_DI (sain par défaut) : capteur TOP libre en simu,
// sauf stimulus manuel SimTopPositionActive (injection de fait capteur au banc).
Winch.M1M2_TopPositionFree_DI  := NOT SimTopPositionActive;
Winch.M2_TensionedCable_DI     := TRUE; // Câble tendu en simu

Winch.COD1_PosValue            := instSimEncoderM1.RawPosOut;
Winch.COD1_Alarms              := 0;
Winch.COD1_Warnings            := 0;
Winch.COD1_DeviceState         := DEVICE_STATE.RUNNING; // État device RUNNING (bus OK)

Winch.COD2_PosValue            := instSimEncoderM2.RawPosOut;
Winch.COD2_Alarms              := 0;
Winch.COD2_Warnings            := 0;
Winch.COD2_DeviceState         := DEVICE_STATE.RUNNING; // État device RUNNING


{endregion}

{region "§3 Simulation translation M3"}
// ── 2. MODÈLE TRANSLATION M3 (AC600) ─────────────────────────────────────────
M3_RelayFwd := M3_ReqTremie AND NOT M3_ReqMaintenance;
M3_RelayRev := M3_ReqMaintenance AND NOT M3_ReqTremie;

instSimTranslation(
    Enable          := TRUE,
    ReqTremie       := M3_RelayFwd,
    ReqMaintenance  := M3_RelayRev,
    SpeedTgt_Pct    := M3_SpeedCmd_Pct,
    FullTravelTimeS := CST_M3FullTravelTimeS
);

// Remplissage capteurs de position M3 : l'override manuel conserve exactement le
// même ordre que FB_Translation_PositionDecoder (bit4=Trémie ... bit0=Maintenance).
IF SimM3SensorsWordOverrideActive THEN
    Translation.M3_PosTremie_DI      := SimM3SensorsWord.4;
    Translation.M3_PosPV_DI          := SimM3SensorsWord.3;
    Translation.M3_PosPVP2_DI        := SimM3SensorsWord.2;
    Translation.M3_PosP1_DI          := SimM3SensorsWord.1;
    Translation.M3_PosMaintenance_DI := SimM3SensorsWord.0;
ELSE
    Translation.M3_PosTremie_DI      := instSimTranslation.PosTremie;
    Translation.M3_PosPV_DI          := instSimTranslation.PosPV;
    Translation.M3_PosPVP2_DI        := instSimTranslation.PosP2;
    Translation.M3_PosP1_DI          := instSimTranslation.PosP1;
    Translation.M3_PosMaintenance_DI := instSimTranslation.PosMaintenance;
END_IF;

// Polarité frein M3 (1 = OUVERT)
Translation.M3_BrakeIsOpen_DI    := M3_BrakeCmd;

// Thermique moteur/variateur AC600 — pas de panne simulée, toujours OK (comme Winch.M1/M2_ThermalOk_DI)
Translation.M3_ThermalOK_DI      := TRUE;

// Simulation StatusWord AC600 : Bit 0 (Power Ready) = 1, Bit 7 (Comm Ready) = 1 -> 16#0087 en mouvement
// Bit0 retombe à l'arrêt, cohérent avec un variateur qui confirme l'arrêt sans rester "actif" —
// FB_Safety_Translation lit ce bit comme indicateur "mouvement non commandé" (Méca B, TonMecaB 3s) :
// un Bit0 forcé à 1 en continu à l'arrêt déclencherait un PowerCutOff simulé permanent après 3s.
// DrivePowerReady (diagnostic IHM seul, non consommé par un interlock) est le seul autre lecteur,
// aucune régression de mouvement possible.
IF M3_RelayFwd OR M3_RelayRev THEN
    M3_StatusWordSim := 16#0087; // + Operating/Running
    M3_ActualFreqHz  := REAL_TO_UINT(M3_SpeedCmd_Pct * 50.0); // 50.0 Hz à 100% (x100 -> 5000)
ELSE
    M3_StatusWordSim := 16#0080; // Comm Ready seul -- Bit0 retombé, arrêt confirmé
    M3_ActualFreqHz  := 0;
END_IF;

Translation.M3_StatusWord        := M3_StatusWordSim;
Translation.M3_ActualFrequencyHz := M3_ActualFreqHz;
Translation.AC600_DeviceState    := DEVICE_STATE.RUNNING; // État device RUNNING


{endregion}

{region "§4 Simulation operateur joystick"}
// ── 3. MODÈLE OPÉRATEUR / JOYSTICK ───────────────────────────────────────────
instSimJoystick(
    Enable              := TRUE,
    NeutralRaw          := 5000,
    MaxRaw              := 10000,
    BtnLeft_Rev_TREMIE  := SimJoystickLeft_Rev_TREMIE_Active,
    BtnRight_Fwd_MAINT  := SimJoystickRight_Fwd_MAINT_Active,
    BtnFwd_Up_Close     := SimJoystickFwd_Up_Close_Active,
    BtnRev_Down_Open    := SimJoystickRev_Down_Open_Active,
    OvershootActive     := SimJoystickOvershoot_Active,
    BagotementActive    := SimJoystickBagotement_Active,
    CycleTimeS          := 0.010
);

// Les boutons directionnels simplifient les essais : une commande unique impose
// une butée d'axe ; aucune commande ou une combinaison reste au neutre / stimulus avancé.
// Le modèle dynamique (montée/retombée/bagotement) pilote RawX/RawY dès qu'un bouton est actif.
SimJoystickDirectionCount := BOOL_TO_INT(SimJoystickLeft_Rev_TREMIE_Active)
                           + BOOL_TO_INT(SimJoystickRight_Fwd_MAINT_Active)
                           + BOOL_TO_INT(SimJoystickFwd_Up_Close_Active)
                           + BOOL_TO_INT(SimJoystickRev_Down_Open_Active);
IF (SimJoystickDirectionCount >= 1) OR instSimJoystick.ReturningActive THEN
    // Bouton(s) actif(s) OU retour dynamique en cours (retombée/bagotement) → sortie du modèle.
    // (≥2 boutons : le modèle gère lui-même le neutre — pas de diagonale implicite.)
    Operator.JoyXRaw_ANA1 := instSimJoystick.RawX;
    Operator.JoyYRaw_ANA2 := instSimJoystick.RawY;
ELSE
    // Modèle au repos → stimulus analogique avancé (mode « sans bouton »).
    Operator.JoyXRaw_ANA1 := SimJoystickRawX;
    Operator.JoyYRaw_ANA2 := SimJoystickRawY;
END_IF;

// Homme-mort : stimulus brut amont. En simulation avec boutons directionnels actifs,
// l'appui homme-mort est automatiquement inclus pour faciliter les essais sur banc.
Operator.JoyBtnRaw := SimJoystickRawButton OR (SimJoystickDirectionCount > 0);

Operator.CanBusState      := 2; // CANbusState 2 = ACTIVE
Operator.JOY1_DeviceState := DEVICE_STATE.RUNNING; // État device RUNNING


{endregion}

{region "§5 Simulation securite et image machine"}
// ── 4. MODÈLE SÉCURITÉ & COMMUNS MACHINE ─────────────────────────────────────
instSimSafety(
    Enable            := TRUE,
    SimChainOkBit     := SimChainOkBit,
    PowerCutOff_A     := PowerKeepAlive_A,
    PowerCutOff_B     := PowerKeepAlive_B,
    PowerCutOffRequest:= PowerCutOffRequest,
    EmergencyArming   := EmergencyArming_RQ,
    BtnEmergencyStop  := BtnEmergencyStop,
    TestCutActive     := TestCutActive
);

Machine.PowerContactorEngaged_DI   := instSimSafety.SimContactorOk;
Machine.EmergencyChainClosed_DI    := instSimSafety.SimChainOk;
Machine.PhaseRotationOk_DI             := TRUE;
Machine.M1_M2_M3_BrakeThermalOk_DI     := TRUE;
Machine.M1_M2_KoboldBottomTouch_DI     := SimKoboldContactValue;
Machine.HydraulicThermalOk_DI          := TRUE;
Machine.TremieFull_OR_GateRaised_DI    := FALSE; // Pas encore câblé, simulé inactif par défaut

// ✅ Cycle de simulation terminé : les 4 images sont publiées pour ce scan
Busy := FALSE;
Done := TRUE;

{endregion}

// 🛡️ 1. GATE GENERAL (D-A11, C1) — PAS de Homed : non-reference ≠ incoherent.
//    Ce gate sert a la fiabilite de la mesure (vitesse, mouvements, PositionsValid).
EncoderFault := (NOT EncoderAvailable) OR EncoderIncoherent;

// 🎯 2. GATE STRICT — reserve a l'interlock hauteur M3 (C1) : on ne translate pas
//    si la hauteur est inconnue (jamais home) ou douteuse.
HomedAndReliable := EncoderAvailable AND Homed AND (NOT EncoderIncoherent);

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Encoder_Abs) ===

{region "§1 Causes & Socle Défaut (évalué en continu)"}
// 🔑 1. RESET FRONT
ResetEdge(CLK := Reset);

// 🔍 2. DIAGNOSTIC BUS / ALARME (Cause 0 : live)
instCauses[0].Active   := (AlarmsIn <> 0) OR NOT SlaveOperational;
instCauses[0].Latching := FALSE;
instCauses[0].Texte    := 'Defaut communication EtherCAT codeur absolu';

// ⏱️ 3. TIMEOUT PRESET (Cause 1 : latched)
IF ResetEdge.Q AND (PresetSeqStep = 0) THEN
    PresetTimeoutError := FALSE;
END_IF;
instCauses[1].Active   := PresetTimeoutError;
instCauses[1].Latching := TRUE;
instCauses[1].Texte    := 'Timeout sequence preset SDO codeur';

// Appel du socle de défaut
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;

EncoderAvailable := NOT instCauses[0].Active;
{endregion}

{region "§2 Gate neutralisation"}
// 🛑 2. GATE
IF NOT Enable THEN
    EncoderAvailable := FALSE;
    Ready := FALSE;
    PresetTriggerCmd := 0; CodeSeqTriggerCmd := 0; PresetValueOut := 0;
    PresetSeqStep := 0;
    PresetCompleted := FALSE;
    PresetTimer(IN := FALSE, PT := PresetTimeout);
    PresetTimerVisual(IN := FALSE, PT := T#500MS);
    // RawPos, AngleRaw et TurnCount sont volontairement gelés hors Enable
    // (AF09 F09.01 / AC5) : aucune lecture bus ni remise a zero dans ce gate.
    RETURN;
END_IF;

Ready := Enable AND NOT Fault.Latched;
{endregion}

{region "§3 Lecture position"}
// 📥 3. LECTURE POSITION — GELER SUR DOUTE (Partie10 §6)
// Si EncoderAvailable=FALSE : RawPos/AngleRaw/TurnCount conservent leur dernière valeur (pas de RETURN
// global ici pour ne pas geler aussi la séquence preset/l'état — seule la lecture est gelée).
IF EncoderAvailable THEN
    RawPos := RawPosIn;   // Sens de comptage géré côté codeur (CoE 6000h bit0, startup parameter CODESYS) — voir Partie10 §3bis. Plus de calcul ici.
    AngleRaw := UDINT_TO_UINT(RawPos MOD PointsPerRev);
    TurnCount := RawPos / PointsPerRev;
END_IF;
{endregion}

{region "§4 Séquence preset"}
// 🔧 4. SÉQUENCE PRESET (écriture bus)
// PresetTriggerCmd := 2 déclenche le référencement à PresetValue (valeur de commande, pas un
// masque de bits). CodeSeqTriggerCmd : rôle non identifié — laissé à 0, PAS piloté tant que sa
// fonction n'est pas confirmée. Ne jamais lui donner une valeur arbitraire.
PresetReqEdge(CLK := PresetRequest);
PresetCompleted := FALSE;
CodeSeqTriggerCmd := 0;                 // non piloté — rôle inconnu, voir note ci-dessus
CASE PresetSeqStep OF
    0: // IDLE
        PresetTriggerCmd := 0;
        IF PresetReqEdge.Q AND EncoderAvailable THEN
            PresetValueOut := PresetValue;
            PresetSeqStep := 1;
            PresetTimer(IN := TRUE, PT := PresetTimeout);
        END_IF;
    1: // Déclenchement preset (laissé actif pendant 0.5s pour confort visuel en simulation/bus)
        PresetTriggerCmd := 2;   // Référence le codeur à PresetValueOut
        RawDiff := UDINT_TO_DINT(RawPos) - UDINT_TO_DINT(PresetValueOut);
        IF ABS(RawDiff) <= UDINT_TO_DINT(PresetTolerancePts) THEN
            PresetTimer(IN := FALSE, PT := PresetTimeout);
            PresetTimerVisual(IN := TRUE, PT := T#500MS);
            IF PresetTimerVisual.Q THEN
                PresetTriggerCmd := 0;
                PresetCompleted := TRUE;
                PresetSeqStep := 0;
                PresetTimerVisual(IN := FALSE, PT := T#500MS);
            END_IF;
        ELSIF PresetTimer.Q THEN
            PresetTriggerCmd := 0;
            PresetTimeoutError := TRUE;
            PresetSeqStep := 0;
            PresetTimer(IN := FALSE, PT := PresetTimeout);
            PresetTimerVisual(IN := FALSE, PT := T#500MS);
        END_IF;
END_CASE;
{endregion}

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Encoder_Homing) ===

{region "§1 Causes & Socle Défaut (évalué en continu)"}
// 🔑 1. FRONTS
ResetEdge(CLK := Reset);
HomeEdge(CLK := Home);
ConfirmCoherenceEdge(CLK := BtnConfirmCoherence);

// Effacement des latches d'erreur sur Reset conscient
IF ResetEdge.Q THEN
    PresetConfirmationFailed := FALSE;
    HomingModeError := FALSE;
    TargetOutOfRangeError := FALSE;
    PresetFailError := FALSE;
END_IF;

// Levée de doute incohérence boot (BtnConfirmCoherence)
IF ConfirmCoherenceEdge.Q AND HomingPermit THEN
    Calib.HomingSuspect := FALSE;
    BootIncoherentError := FALSE;
END_IF;

// Configuration des causes nommées
instCauses[0].Active   := HomingModeError;
instCauses[0].Latching := TRUE;
instCauses[0].Texte    := 'Homing non autorise dans ce mode';

instCauses[1].Active   := TargetOutOfRangeError;
instCauses[1].Latching := TRUE;
instCauses[1].Texte    := 'Cible de homing hors plage';

instCauses[2].Active   := PresetFailError;
instCauses[2].Latching := TRUE;
instCauses[2].Texte    := 'Echec confirmation transaction preset';

instCauses[3].Active   := BootIncoherentError;
instCauses[3].Latching := TRUE;
instCauses[3].Texte    := 'Incoherence position codeur au demarrage';

// Appel du socle de défaut
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;
{endregion}

{region "§2 Gate neutralisation"}
// 🛑 2. GATE — neutralisation ; on continue toutefois d'exposer le dernier état RETAIN connu
// (FB_Encoder_Scale a besoin de HomingRefRaw même si ce FB est désactivé)
IF NOT Enable THEN
    PresetRequest := FALSE;
    PresetValue := 0;
    Ready := FALSE;
    Lifecycle.Busy := FALSE;
    Lifecycle.Done := FALSE;
    InitDone := FALSE;   // Force un nouveau contrôle à la prochaine activation
    PresetVerificationActive := FALSE;
    PresetVerifyTimer(IN := FALSE, PT := CST_PresetVerifyTime);
    Homed := Calib.Homed;
    HomingSuspect := Calib.HomingSuspect;
    HomingRefRaw := Calib.HomingRefRaw;
    // PresetConfirmationFailed est un diagnostic latch : il est gelé hors Enable
    RETURN;
END_IF;

Ready := Enable AND NOT Fault.Latched;
{endregion}

{region "§3 Cohérence au redémarrage"}
// 🔍 3. COHÉRENCE AU REDÉMARRAGE — une fois par session Enable, dès que le codeur répond
IF NOT InitDone THEN
    IF EncoderAvailable THEN
        RawDiffRestart := UDINT_TO_DINT(RawPos) - UDINT_TO_DINT(Calib.LastKnownRawPos);
        IF Calib.Homed AND (ABS(RawDiffRestart) > UDINT_TO_DINT(Calib.RestartCoherenceTolerancePts)) THEN
            Calib.HomingSuspect := TRUE;
            BootIncoherentError := TRUE;
        END_IF;
        InitDone := TRUE;
    END_IF;
END_IF;
{endregion}

{region "§4 Demande et déclenchement homing"}
// ⚙️ 4. DEMANDE & DÉCLENCHEMENT HOMING
PresetRequest := FALSE;
PresetValue := 0;
TopSensorEdge(CLK := TopPositionSensor);
DynamicTargetEdge(CLK := UseDynamicTarget);

HomingModeOk := HomingPermit;

IF HomeEdge.Q AND NOT HomingModeOk THEN
    HomingModeError := TRUE;
END_IF;

NominalHomingTrigger := HomingModeOk AND NOT UseDynamicTarget
                         AND ((Home AND TopSensorEdge.Q) OR (HomeEdge.Q AND TopPositionSensor));

UnitaryHomingTrigger := HomingModeOk AND NOT UseDynamicTarget AND HomeEdge.Q;

DynamicHomingTrigger := HomingModeOk AND (DynamicTargetEdge.Q OR (UseDynamicTarget AND HomeEdge.Q));

HomingTrigger := (NominalHomingTrigger OR UnitaryHomingTrigger OR DynamicHomingTrigger)
                 AND NOT PresetVerificationActive;

IF HomingTrigger THEN
    IF UseDynamicTarget THEN
        TargetPositionM := DynamicHomingTargetM;
    ELSIF NominalHomingTrigger THEN
        TargetPositionM := CfgTopSensorPosM;
    ELSE
        TargetPositionM := CfgHomingTargetM;
    END_IF;

    // Bornage obligatoire avant écriture (CODE_QUALITY_STANDARDS §6) [-99;+99] m
    IF (TargetPositionM < -99.0) OR (TargetPositionM > 99.0) THEN
        TargetOutOfRangeError := TRUE;
    ELSE
        TargetPoints := REAL_TO_DINT(TargetPositionM * UDINT_TO_REAL(PointsPerRev) / CableM_PerRev);
        PendingHomingRefRaw := DINT_TO_UDINT(UDINT_TO_DINT(RawPos) - TargetPoints);
        PresetValue := RawPos;
        PresetRequest := TRUE;
        PresetVerificationActive := TRUE;
        Lifecycle.Done := FALSE;
    END_IF;
END_IF;
{endregion}

{region "§5 Suivi de transaction preset"}
// ⏳ 5. SUIVI DE LA TRANSACTION PRESET
PresetVerifyTimer(IN := PresetVerificationActive, PT := CST_PresetVerifyTime);
IF PresetVerificationActive AND PresetVerifyTimer.Q THEN
    CandidateRawDiff := UDINT_TO_DINT(RawPos) - UDINT_TO_DINT(PendingHomingRefRaw);
    IF PointsPerRev <> 0 THEN
        CandidateCablePosM := DINT_TO_REAL(CandidateRawDiff) * CableM_PerRev / UDINT_TO_REAL(PointsPerRev);
    ELSE
        CandidateCablePosM := 0.0;
    END_IF;
    ReadbackOk := ABS(CandidateCablePosM - TargetPositionM) <= CST_HomingVerifyToleranceM;
    StatusBitOk := PresetStatusBit;

    CASE Cfg.PresetConfirmMode OF
        E_PresetConfirmMode.READBACK_ONLY:
            PresetConfirmed := ReadbackOk;
        E_PresetConfirmMode.READBACK_AND_STATUSBIT:
            PresetConfirmed := ReadbackOk AND StatusBitOk;
        E_PresetConfirmMode.STATUSBIT_ONLY:
            PresetConfirmed := StatusBitOk;
        ELSE
            PresetConfirmed := FALSE;
    END_CASE;

    IF PresetConfirmed THEN
        Calib.HomingRefRaw := PendingHomingRefRaw;
        Calib.Homed := TRUE;
        Calib.HomingSuspect := FALSE;
        Calib.LastKnownRawPos := RawPos;
        PresetConfirmationFailed := FALSE;
        PresetFailError := FALSE;
        Lifecycle.Done := TRUE;
    ELSE
        Calib.HomingSuspect := TRUE;
        PresetConfirmationFailed := TRUE;
        PresetFailError := TRUE;
        Lifecycle.Done := FALSE;
    END_IF;

    PresetVerificationActive := FALSE;
    PresetVerifyTimer(IN := FALSE, PT := CST_PresetVerifyTime);
END_IF;
{endregion}

{region "§6 Sorties état & calibration"}
// 📤 6. SORTIES ÉTAT & CALIBRATION
IF EncoderAvailable AND NOT PresetVerificationActive THEN
    Calib.LastKnownRawPos := RawPos;
END_IF;

Lifecycle.Busy := PresetVerificationActive;
Homed := Calib.Homed AND NOT Calib.HomingSuspect;
HomingSuspect := Calib.HomingSuspect;
HomingRefRaw := Calib.HomingRefRaw;
{endregion}

// === IMPLEMENTATION ===

{region "§1 Causes & Socle Défaut (évalué en continu)"}
// 🔑 1. RESET FRONT
ResetEdge(CLK := Reset);

// 🔍 2. SURVEILLANCE BORNAGE & INCOHÉRENCE BOOT
instCauses[0].Active   := NOT BypassGlobal AND ((CablePosM < PositionMinM) OR (CablePosM > PositionMaxM));
instCauses[0].Latching := FALSE;
instCauses[0].Texte    := 'Depassement bornes physiques absolues cable';

instCauses[1].Active   := NOT BypassGlobal AND HomingSuspect;
instCauses[1].Latching := FALSE;
instCauses[1].Texte    := 'Incoherence position au redemarrage';

// Appel du socle de défaut
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;
{endregion}

{region "§2 Gate neutralisation"}
// 🛑 2. GATE
IF NOT Enable THEN
    Ready := FALSE;
    CablePosMSafe := CablePosM;
    EncoderIncoherent := FALSE;
    RETURN;
END_IF;

Ready := Enable AND NOT Fault.Latched;
{endregion}

{region "§3 Transmission mesure et sécurité"}
// 📏 3. TRANSMISSION DE LA MESURE & SÉCURITÉ
CablePosMSafe := CablePosM;
EncoderIncoherent := Fault.Error;
{endregion}

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Encoder_Scale) ===

// 🧮 Écart signé sûr : conversion DINT AVANT soustraction (§3.1) — jamais l'inverse
RawDiff := UDINT_TO_DINT(RawPos) - UDINT_TO_DINT(HomingRefRaw);

// 📏 Formule fixe points → mètres (Partie10 §2), garde division par zéro
IF PointsPerRev > 0 THEN
    CablePosM := DINT_TO_REAL(RawDiff) * (CableM_PerRev / UDINT_TO_REAL(PointsPerRev));
ELSE
    CablePosM := 0.0;
END_IF;

{region "§1 Horodatage et purge"}
// ⏱️ Horodatage natif : le calcul utilise le temps réellement écoulé, jamais un cycle supposé.
CurrentTimestamp := TIME();

// Purge des six positions sur rupture de confiance : aucune source antérieure ne peut contaminer la mesure.
IF NOT Enable OR Reset OR NOT PositionValid THEN
    Speed_Mps := 0.0;
    SignedSpeed_Mps := 0.0;
    Valid := FALSE;
    CollectedSamples := 0;
    TimestampInitialized := FALSE;
    RETURN;
END_IF;
{endregion}

{region "§2 Première position"}
// 🕒 Première position de la nouvelle fenêtre.
IF NOT TimestampInitialized THEN
    Positions_M[0] := Position_M;
    Timestamps[0] := CurrentTimestamp;
    LastTimestamp := CurrentTimestamp;
    CollectedSamples := 1;
    TimestampInitialized := TRUE;
    Speed_Mps := 0.0;
    SignedSpeed_Mps := 0.0;
    Valid := FALSE;
    RETURN;
END_IF;
{endregion}

{region "§3 Rebouclage TIME"}
// 🛡️ Rebouclage de TIME détecté localement : purge sans réutiliser le delta aberrant.
IF CurrentTimestamp < LastTimestamp THEN
    Positions_M[0] := Position_M;
    Timestamps[0] := CurrentTimestamp;
    LastTimestamp := CurrentTimestamp;
    CollectedSamples := 1;
    Speed_Mps := 0.0;
    SignedSpeed_Mps := 0.0;
    Valid := FALSE;
    RETURN;
END_IF;

ElapsedSinceSample := CurrentTimestamp - LastTimestamp;

// 🛡️ Delta nul : aucune division et aucun doublon d'échantillon.
IF ElapsedSinceSample <= T#0MS THEN
    RETURN;
END_IF;
{endregion}

{region "§4 Collecte échantillons"}
// 📥 Six positions espacées d'au moins 10 ms donnent cinq intervalles sur la fenêtre interne de 50 ms.
IF ElapsedSinceSample >= SamplePeriod THEN
    LastTimestamp := CurrentTimestamp;

    IF CollectedSamples < SampleCount THEN
        Positions_M[CollectedSamples] := Position_M;
        Timestamps[CollectedSamples] := CurrentTimestamp;
        CollectedSamples := CollectedSamples + 1;
    ELSE
        FOR Index := 0 TO 4 DO
            Positions_M[Index] := Positions_M[Index + 1];
            Timestamps[Index] := Timestamps[Index + 1];
        END_FOR;
        Positions_M[5] := Position_M;
        Timestamps[5] := CurrentTimestamp;
    END_IF;
{endregion}

{region "§5 Calcul vitesse"}
    IF CollectedSamples = SampleCount THEN
        // 🛡️ Ordre temporel et durée minimale contrôlés avant toute conversion/division.
        IF Timestamps[5] >= Timestamps[0] THEN
            WindowElapsed := Timestamps[5] - Timestamps[0];
            IF WindowElapsed >= WindowTime THEN
                SignedSpeed_Mps := (Positions_M[5] - Positions_M[0])
                                   / (UDINT_TO_REAL(TIME_TO_UDINT(WindowElapsed)) / 1000.0);
                Speed_Mps := ABS(SignedSpeed_Mps);
                Valid := TRUE;
            ELSE
                Speed_Mps := 0.0;
                SignedSpeed_Mps := 0.0;
                Valid := FALSE;
            END_IF;
        ELSE
            Speed_Mps := 0.0;
            SignedSpeed_Mps := 0.0;
            Valid := FALSE;
            CollectedSamples := 0;
            TimestampInitialized := FALSE;
        END_IF;
    END_IF;
END_IF;
{endregion}

{region "§1 Reset (front, toujours effectif)"}
// Front Reset : efface tous les latches. Jamais conditionné, agit même Enable=FALSE (§9).
Ready := Enable;
ResetEdge(CLK := Reset);
IF ResetEdge.Q THEN
    FOR i := 0 TO 15 DO Latch[i] := FALSE; END_FOR;
END_IF;
{endregion}

{region "§2 Vue LIVE — Error / ErrorId"}
// Bitfield des causes présentes MAINTENANT. Retombe seule à 0 quand les causes disparaissent.
// Non évaluée si Enable=FALSE (pas de lecture de cause hors autorisation).
Fault.ErrorId := 0;
IF Enable THEN
    FOR i := 0 TO 15 DO
        IF Causes[i].Active THEN
            Fault.ErrorId := Fault.ErrorId OR SHL(WORD#1, INT_TO_DWORD(i));
        END_IF;
    END_FOR;
END_IF;
Fault.Error := (Fault.ErrorId <> 0);
{endregion}

{region "§3 Armement des latches (causes à acquitter)"}
// Une cause Active ET Latching arme son bit ; le bit reste jusqu'au front Reset (§1),
// même si la cause disparaît. Réapparition => ré-armement (ré-alarme).
IF Enable THEN
    FOR i := 0 TO 15 DO
        IF Causes[i].Active AND Causes[i].Latching THEN
            Latch[i] := TRUE;
        END_IF;
    END_FOR;
END_IF;
{endregion}

{region "§4 Vue LATCHÉE — Latched / LatchedId"}
// Toujours publiée, y compris Enable=FALSE : un défaut non acquitté reste visible.
Fault.LatchedId := 0;
FOR i := 0 TO 15 DO
    IF Latch[i] THEN
        Fault.LatchedId := Fault.LatchedId OR SHL(WORD#1, INT_TO_DWORD(i));
    END_IF;
END_FOR;
Fault.Latched := (Fault.LatchedId <> 0);
{endregion}

IF RawIn >= Neutral THEN
    Delta := INT_TO_REAL(10000 - Neutral);
    IF Delta > 0.0 THEN
        OutPct := (INT_TO_REAL(RawIn - Neutral) / Delta) * 100.0;
    ELSE
        OutPct := 0.0;
    END_IF;
ELSE
    Delta := INT_TO_REAL(Neutral);
    IF Delta > 0.0 THEN
        OutPct := (INT_TO_REAL(RawIn - Neutral) / Delta) * 100.0;
    ELSE
        OutPct := 0.0;
    END_IF;
END_IF;

IF ABS(RawIn - Neutral) <= DeadbandRaw THEN
    OutPct := 0.0;
END_IF;

// 🛡️ Limitation de plage : une valeur brute hors plage nominale ne doit jamais
// produire une consigne supérieure à ±100 %. Ce garde-fou protège les
// consommateurs en aval, notamment la translation M3.
OutPct := LIMIT(-100.0, OutPct, 100.0);

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Sim_Encoder) ===

{region "§1 Gate"}
IF NOT Enable THEN
    RawPosOut := RawPos;
    RETURN;
END_IF;
{endregion}

{region "§2 Injection test"}
// Injection test banc : VRAI saut de position (comme un glissement réel),
// pour tester Concept 1 / Méca E ET le rattrapage joystick (voir GVL_Simulation bandeau).
TestOffsetEdge(CLK := TestOffsetCmd);
IF TestOffsetEdge.Q THEN
    RawPos := DINT_TO_UDINT(UDINT_TO_DINT(RawPos) + TestOffsetPts);
END_IF;
{endregion}

{region "§3 Comptage"}
// 🎚️ Vitesse simulée = interpolation linéaire du palier (palier 1 → MinSpeedMps, palier 5 → MaxSpeedMps),
// pas par pas de (Max−Min)/4. Palier 0 (arrêt) ramène au palier 1 mais aucun mouvement n'est
// appliqué tant que RelayFwd/RelayRev = FALSE (section plus bas).
EffStep  := MAX(StepNumber, 1);
SpeedMps := MinSpeedMps + (INT_TO_REAL(EffStep) - 1.0) * ((MaxSpeedMps - MinSpeedMps) / 4.0);
// Points par cycle = vitesse (m/s) × points par mètre × période tâche (s) × facteur confort.
Increment := REAL_TO_UDINT(SpeedMps * (UDINT_TO_REAL(PointsPerRev) / CableM_PerRev) * CycleTimeS * SpeedScaleFactor);

// Front du preset : lance la latence de referencement (le codeur réel n'est pas
// instantane — il met PresetLatencyCycles cycles a se re-referencer apres le front).
PresetEdge(CLK := PresetCmd);
IF PresetEdge.Q THEN
    PresetPending := TRUE;
    PresetCount := PresetLatencyCycles;
END_IF;

// Pendant l'attente, la position brute est conservee (le codeur n'a pas encore re-reference).
// Le mouvement est gelé pendant la latence, comme un codeur réel en cours de referencement.
IF PresetPending THEN
    IF PresetCount > 0 THEN
        PresetCount := PresetCount - 1;
    ELSE
        // Latence écoulée : applique la valeur cible du preset.
        RawPos := PresetValue;
        PresetPending := FALSE;
    END_IF;
ELSIF RelayFwd THEN
    RawPos := RawPos + Increment;
ELSIF RelayRev THEN
    IF RawPos >= Increment THEN
        RawPos := RawPos - Increment;
    ELSE
        RawPos := 0;
    END_IF;
END_IF;
{endregion}

{region "§4 Sortie"}
RawPosOut := RawPos;
{endregion}

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Sim_Joystick) ===

{region "§1 Gate"}
// 🔑 Initialise au neutre au premier cycle uniquement ; ensuite RawX/RawY sont pilotés
// dynamiquement par les boutons. Quand la simulation est coupée, on revient au neutre.
IF NOT Enable THEN
    FirstCycle := TRUE;
    State      := CST_ST_IDLE;
    RawX       := NeutralRaw;
    RawY       := NeutralRaw;
    RawButton  := FALSE;
    ReturningActive := FALSE; // 📊 Neutralisation : simulation inactive hors Enable
    RETURN;
END_IF;
{endregion}

{region "§2 Initialisation neutre"}
IF FirstCycle THEN
    RawX       := NeutralRaw;
    RawY       := NeutralRaw;
    RawButton  := FALSE;
    State      := CST_ST_IDLE;
    FirstCycle := FALSE;
END_IF;
{endregion}

{region "§3 Pseudo-aléatoire (bruit de montée)"}
// 🎲 Compteur qui repasse à zéro, multiplié pour rester dans la plage (méthode validée).
// Le bruit s'ajoute à la rampe de montée uniquement (pas à la retombée, linéaire propre).
RandCnt := (RandCnt + 1) MOD 1000;
Noise   := (RandCnt MOD 50) - 25;   // ±25 points (≈ ±0.5% de la course)
{endregion}

{region "§4 Cibles & transitions"}
// 🎯 Un SEUL bouton impose une butée d'axe ; 0 ou ≥2 boutons = neutre (pas de diagonale implicite).
// Si OvershootActive : la cible de montée DÉPASSE la butée (MaxRaw+AMT ou 0−AMT) pour
// déclencher le défaut capteur hors plage (RawOutOfRange) — test du dépassement de valeur.
BtnCount := BOOL_TO_INT(BtnLeft_Rev_TREMIE) + BOOL_TO_INT(BtnRight_Fwd_MAINT)
          + BOOL_TO_INT(BtnFwd_Up_Close) + BOOL_TO_INT(BtnRev_Down_Open);
IF BtnCount = 1 THEN
    IF BtnLeft_Rev_TREMIE THEN
        IF OvershootActive THEN TargetX := 0 - CST_OVERSHOOT_AMT; ELSE TargetX := 0; END_IF;
        TargetY := NeutralRaw; ActiveAxis := 1;
    ELSIF BtnRight_Fwd_MAINT THEN
        IF OvershootActive THEN TargetX := MaxRaw + CST_OVERSHOOT_AMT; ELSE TargetX := MaxRaw; END_IF;
        TargetY := NeutralRaw; ActiveAxis := 1;
    ELSIF BtnFwd_Up_Close THEN
        TargetX := NeutralRaw;
        IF OvershootActive THEN TargetY := MaxRaw + CST_OVERSHOOT_AMT; ELSE TargetY := MaxRaw; END_IF;
        ActiveAxis := 2;
    ELSE
        TargetX := NeutralRaw;
        IF OvershootActive THEN TargetY := 0 - CST_OVERSHOOT_AMT; ELSE TargetY := 0; END_IF;
        ActiveAxis := 2;
    END_IF;
    State := CST_ST_RISE;
ELSE
    // 0 ou ≥2 boutons : retour au neutre.
    TargetX := NeutralRaw;
    TargetY := NeutralRaw;
    IF State = CST_ST_RISE THEN
        // Front de relâchement : retour au neutre. D'abord retombée linéaire (FALL),
        // puis petit bagotement de quelques % autour du neutre si OvershootActive (voir §6).
        State := CST_ST_FALL;
    END_IF;
END_IF;
{endregion}

{region "§5 Ascending (rampe + bruit)"}
IF State = CST_ST_RISE THEN
    // Pas de montée : pleine course (MaxRaw−NeutralRaw) en RiseTimeS.
    RiseStep := INT_TO_REAL(MaxRaw - NeutralRaw) / (RiseTimeS / CycleTimeS);
    // Axe X
    IF RawX < TargetX THEN
        RawX := MIN(RawX + REAL_TO_INT(RiseStep) + Noise, TargetX);
    ELSIF RawX > TargetX THEN
        RawX := MAX(RawX - REAL_TO_INT(RiseStep) - Noise, TargetX);
    END_IF;
    // Axe Y
    IF RawY < TargetY THEN
        RawY := MIN(RawY + REAL_TO_INT(RiseStep) + Noise, TargetY);
    ELSIF RawY > TargetY THEN
        RawY := MAX(RawY - REAL_TO_INT(RiseStep) - Noise, TargetY);
    END_IF;
END_IF;
{endregion}

{region "§6 Retombée linéaire (sans bagotement)"}
IF State = CST_ST_FALL THEN
    // Pas de retombée : pleine course en FallTimeMs (TIME_TO_REAL → ms, /1000 → s).
    FallStep := INT_TO_REAL(MaxRaw - NeutralRaw) / (TIME_TO_REAL(FallTimeMs) / 1000.0 / CycleTimeS);
    IF RawX < NeutralRaw THEN
        RawX := MIN(RawX + REAL_TO_INT(FallStep), NeutralRaw);
    ELSIF RawX > NeutralRaw THEN
        RawX := MAX(RawX - REAL_TO_INT(FallStep), NeutralRaw);
    END_IF;
    IF RawY < NeutralRaw THEN
        RawY := MIN(RawY + REAL_TO_INT(FallStep), NeutralRaw);
    ELSIF RawY > NeutralRaw THEN
        RawY := MAX(RawY - REAL_TO_INT(FallStep), NeutralRaw);
    END_IF;
    IF RawX = NeutralRaw AND RawY = NeutralRaw THEN
        // Arrivée au neutre : si bagotement demandé, lance un petit balancement de quelques %.
        IF BagotementActive THEN
            State := CST_ST_OVERSHOOT;
            IF ActiveAxis = 1 THEN
                OscDev := INT_TO_REAL(CST_BAGOT_AMT);
            ELSE
                OscDev := INT_TO_REAL(CST_BAGOT_AMT);
            END_IF;
            OscVel := 0.0;
        ELSE
            State := CST_ST_IDLE;
        END_IF;
    END_IF;
END_IF;
{endregion}

{region "§7 Bagotement (dépassement + oscillations amorties)"}
IF State = CST_ST_OVERSHOOT THEN
    // 🎢 Oscillateur harmonique amorti discret (semi-implicite) autour du neutre :
    // le joystick dépasse le centre (~12% de l'écart initial) puis oscille 1-2 fois
    // avant de se stabiliser — comportement d'un opérateur qui relâche et balance.
    OscAcc := -CST_OSC_K * OscDev - CST_OSC_C * OscVel;
    OscVel := OscVel + OscAcc;
    OscDev := OscDev + OscVel;
    IF ActiveAxis = 1 THEN
        RawX := NeutralRaw + REAL_TO_INT(OscDev);
    ELSE
        RawY := NeutralRaw + REAL_TO_INT(OscDev);
    END_IF;
    // Stabilisé : revient exactement au centre.
    IF ABS(OscDev) < 1.0 AND ABS(OscVel) < 1.0 THEN
        State := CST_ST_IDLE;
        IF ActiveAxis = 1 THEN
            RawX := NeutralRaw;
        ELSE
            RawY := NeutralRaw;
        END_IF;
    END_IF;
END_IF;
{endregion}

{region "§8 Homme-mort brut + drapeau retour"}
RawButton := BtnLeft_Rev_TREMIE OR BtnRight_Fwd_MAINT OR BtnFwd_Up_Close OR BtnRev_Down_Open;
// Drapeau "retour dynamique en cours" : TRUE si l'état est FALL ou OVERSHOOT (retombée/bagotement).
// Permet à FB_SimBench d'émettre la sortie du modèle même après relâchement du bouton.
ReturningActive := (State = CST_ST_FALL) OR (State = CST_ST_OVERSHOOT);
{endregion}

// === IMPLEMENTATION ===
{region "§1 Gate"}
IF NOT Enable THEN
    SimChainOk     := FALSE;
    SimContactorOk := FALSE;
    ContactorLatch := FALSE;
    ChainOpen      := TRUE; // Chaîne ouverte par défaut à la ré-entrée (on n'a pas armé)
    ChainOpenReq   := FALSE;
    ContactorEngageReq := FALSE;
    TonChainOpen(IN := FALSE);
    TonChainClose(IN := FALSE);
    TonContactorEngage(IN := FALSE);
    TonContactorDrop(IN := FALSE);
    RETURN;
END_IF;
{endregion}

{region "§2 Chaîne AU (contrôle granulaire + dynamique)"}
// 1. La chaîne AU est saine si l'opérateur la simule fermée (SimChainOkBit = TRUE) ET si aucun
//    événement ne l'ouvre : coup-de-poing (BtnEmergencyStop), test de redondance (TestCutActive),
//    coupure métier (PowerCutOffRequest).
// 🔧 DEADLOCK SIMULATION (corrigé) : la chaîne n'est PAS fermée par défaut ni dépendante de
//    PowerCutOff_A/B (qui sont dans le cercle). Elle est fermée UNIQUEMENT par le bit opérateur
//    `SimChainOkBit`. Le réarmement après échec de test de redondance (RedundancyTestFailedCause laté
//    → PowerCutOff_A=FALSE) reste possible car la chaîne est maintenue fermée par le bit, pas par
//    le PLC. Hors simulation (Enable=FALSE), la chaîne reste pilotée par le matériel via le repli
//    HwReal (PRG_02 §1/§2) — aucune régression sécurité réelle.
// 🆕 DYNAMIQUE : l'ouverture/fermeture suit une temporisation (CST_ChainOpenDelay / CST_ChainCloseDelay)
//    qui simule le temps de retombée des relais AU, tout en restant < 200ms (CST_TestDuration) pour
//    ne pas fausser le test de redondance. Pendant le test, la chaîne clignote (s'ouvre en TEST_A/B,
//    se referme en RESTORE_A/B) puis revient à 1.
ChainOpenReq := (NOT SimChainOkBit) OR BtnEmergencyStop OR TestCutActive OR PowerCutOffRequest;

// Temporisation d'ouverture : la chaîne s'ouvre après CST_ChainOpenDelay de demande soutenue
TonChainOpen(IN := ChainOpenReq, PT := CST_ChainOpenDelay);
// Temporisation de fermeture : la chaîne se ferme après CST_ChainCloseDelay d'absence de demande
TonChainClose(IN := NOT ChainOpenReq, PT := CST_ChainCloseDelay);

// Latch de la chaîne avec temporisations (défaut = ouverte à la ré-entrée)
IF ChainOpenReq THEN
    IF TonChainOpen.Q THEN
        ChainOpen := TRUE;
    END_IF;
ELSE
    IF TonChainClose.Q THEN
        ChainOpen := FALSE;
    END_IF;
END_IF;

SimChainOk := NOT ChainOpen;
{endregion}

{region "§3 Auto-maintien contacteur (dynamique réaliste)"}
// 2. Logique d'auto-maintien (latch) du contacteur avec priorité à la coupure.
// 🆕 DYNAMIQUE : le contacteur ne s'engage QUE pendant l'impulsion d'armement (EmergencyArming)
//    tant que la chaîne est saine, après CST_ContactorEngageDelay (temps de collage bobine), puis
//    s'auto-maintient. Il retombe après CST_ContactorDropDelay (temps de décollage bobine) dès que
//    la chaîne s'ouvre — comme une bobine réelle qui décolle sans alimentation. Ces temporisations
//    restent < CST_ArmingPulseDuration (1s) et CST_ArmingConfirmTimeout (2s) pour que la
//    confirmation contacteur reste validée. À la ré-entrée en simulation, le contacteur est NON
//    engagé (on n'a pas armé).
ContactorEngageReq := EmergencyArming AND SimChainOk;

// Temporisation d'engagement : le contacteur se colle après CST_ContactorEngageDelay de pulse soutenu
TonContactorEngage(IN := ContactorEngageReq, PT := CST_ContactorEngageDelay);
// Temporisation de retombée : le contacteur décolle après CST_ContactorDropDelay de chaîne ouverte
TonContactorDrop(IN := NOT SimChainOk, PT := CST_ContactorDropDelay);

// Latch du contacteur avec priorité à la coupure (retombée > engagement)
IF NOT SimChainOk THEN
    IF TonContactorDrop.Q THEN
        ContactorLatch := FALSE;
    END_IF;
ELSIF ContactorEngageReq THEN
    IF TonContactorEngage.Q THEN
        ContactorLatch := TRUE;
    END_IF;
END_IF;

// Recopie vers la sortie
SimContactorOk := ContactorLatch;
{endregion}

// === IMPLEMENTATION ===

{region "§1 Gate"}
IF NOT Enable THEN
    // Prochain démarrage déterministe sur la Trémie (0 m), pour un état de départ propre.
    PositionProgress := CST_PositionAtTremie;
    Initialized := FALSE;
    PosTremie := FALSE;
    PosPV := FALSE;
    PosP2 := FALSE;
    PosP1 := FALSE;
    PosMaintenance := FALSE;
    RETURN;
END_IF;
{endregion}

{region "§2 Initialisation"}
IF NOT Initialized THEN
    PositionProgress := CST_PositionAtTremie;
    Initialized := TRUE;
END_IF;
{endregion}

{region "§3 Progression"}
instCycleTime(DefaultValueS := 0.010);
SpeedPctBounded := LIMIT(0.0, ABS(SpeedTgt_Pct), 100.0);

// Une vitesse à 100 % parcourt les 30 m (Trémie→Maintenance) pendant FullTravelTimeS.
// Les demandes de sens sont des bits explicites ; une demande contradictoire est neutre.
IF FullTravelTimeS >= CST_MinFullTravelTimeS THEN
    PositionIncrement := (SpeedPctBounded / 100.0)
                         * (CST_TotalDistanceM / FullTravelTimeS)
                         * instCycleTime.CycleTimeS;
ELSE
    PositionIncrement := 0.0;
END_IF;

IF ReqTremie AND NOT ReqMaintenance THEN
    PositionProgress := MAX(CST_PositionAtTremie, PositionProgress - PositionIncrement);
ELSIF ReqMaintenance AND NOT ReqTremie THEN
    PositionProgress := MIN(CST_PositionAtMaintenance, PositionProgress + PositionIncrement);
END_IF;
{endregion}

{region "§4 Publication capteurs"}
// Réinitialisation explicite : aucune valeur transitoire héritée d'une zone précédente.
PosTremie := FALSE;
PosPV := FALSE;
PosP2 := FALSE;
PosP1 := FALSE;
PosMaintenance := FALSE;

// Chaque intervalle correspond à un seul mot thermomètre valide.
IF PositionProgress <= CST_PositionAtTremie THEN
    PosTremie := TRUE;
    PosPV := TRUE;
    PosP2 := TRUE;
    PosP1 := TRUE;
    PosMaintenance := TRUE;
ELSIF PositionProgress <= CST_PositionAtPV THEN
    PosPV := TRUE;
    PosP2 := TRUE;
    PosP1 := TRUE;
    PosMaintenance := TRUE;
ELSIF PositionProgress <= CST_PositionAtP2 THEN
    PosP2 := TRUE;
    PosP1 := TRUE;
    PosMaintenance := TRUE;
ELSIF PositionProgress <= CST_PositionAtP1 THEN
    PosP1 := TRUE;
    PosMaintenance := TRUE;
ELSIF PositionProgress < CST_PositionAtMaintenance THEN
    PosMaintenance := TRUE;
END_IF;
{endregion}

{region "§1 Acquisition temps"}
// 1. ACQUISITION DU TEMPS SYSTÈME
TimeCurrent := TIME();
{endregion}

{region "§2 Initialisation"}
// 2. INITIALISATION UNIQUE AU PREMIER CYCLE
IF NOT InitDone THEN
    TimeLast := TimeCurrent;
    InitDone := TRUE;
    CycleTimeS := DefaultValueS;
    RETURN;
END_IF;
{endregion}

{region "§3 Calcul delta"}
// 3. CALCUL DU DELTA EN MILLISECONDES
DeltaTimeMs := TIME_TO_UDINT(TimeCurrent - TimeLast);
{endregion}

{region "§4 Conversion, secours et bornage"}
// 4. CONVERSION EN SECONDES, AVEC DOUBLE BORNAGE DU DELTA
//
// TIME() est un compteur systeme 32 bits en millisecondes depuis le demarrage de
// l'automate. Il n'est PAS absolu : il reboucle a 0 tous les 2^32 ms (~49,7 jours).
// La soustraction TimeCurrent - TimeLast est modulo 2^32 : au passage du rebouclage,
// tant que l'ecart reel entre deux scans reste < 49,7 j (toujours vrai a 10 ms),
// DeltaTimeMs reste correct. Le rebouclage seul n'est donc pas le risque principal.
//
// Le vrai risque est un DeltaTimeMs REELLEMENT > CST_MaxCycleDeltaMs : reprise apres
// un online-change, sortie d'un point d'arret / pas-a-pas debug, ou fenetre du
// rebouclage TIME(). Le chien de garde tache (200 ms, sensibilite 1) borne deja les
// gels en fonctionnement ; ce plafond couvre les cas hors surveillance.
// Un dt aberrant publie tel quel donnerait un CycleTimeS enorme, propage en un seul
// scan dans les rampes de vitesse et les integrateurs de position/frein -> saut
// physique. Fail-safe : hors de la plage nominale (0 < dt <= plafond), on publie la
// valeur de secours DefaultValueS au lieu de l'artefact. Pas de redemarrage auto.
//
// Borne basse dt = 0 (anti-zero, ex. premier appel du scan) et borne haute
// dt > CST_MaxCycleDeltaMs (anti-artefact) partagent la meme branche de secours.
IF (DeltaTimeMs > 0) AND (DeltaTimeMs <= CST_MaxCycleDeltaMs) THEN
    CycleTimeS := UDINT_TO_REAL(DeltaTimeMs) / 1000.0;
ELSE
    CycleTimeS := DefaultValueS;
END_IF;
{endregion}

{region "§5 Archivage"}
// 5. ARCHIVAGE POUR LE PROCHAIN CYCLE
TimeLast := TimeCurrent;
{endregion}
